        wrap.add(pair);
        wrap.add(Box.createVerticalStrut(5));

        resumeTrip.setAlignmentX(Component.LEFT_ALIGNMENT);
        Styles.capHeight(resumeTrip);
        wrap.add(resumeTrip);

