        return wrap;
    }

    private JPanel currentCard() {
        JPanel card = Styles.card();

        JPanel tiles = new JPanel(new GridLayout(1, 2, 6, 0));
        tiles.setBackground(Styles.CARD);
        tiles.setAlignmentX(Component.LEFT_ALIGNMENT);
        tiles.add(Styles.tile(tripGpHr, "GP/hr", Styles.GP));
        tiles.add(Styles.tile(tripXpHr, "XP/hr", Styles.XP));
        Styles.capHeight(tiles);
        card.add(tiles);
        card.add(Box.createVerticalStrut(6));

        JPanel grid = new JPanel(new GridLayout(0, 2, 0, 3));
        grid.setBackground(Styles.CARD);
        grid.setAlignmentX(Component.LEFT_ALIGNMENT);
        grid.add(Styles.keyLabel("Loot picked"));
        grid.add(picked);
        grid.add(Styles.keyLabel("On ground"));
        grid.add(ground);
        grid.add(Styles.keyLabel("Supplies"));
        grid.add(supplies);
        grid.add(Styles.keyLabel("Gathered"));
        grid.add(gathered);
        grid.add(Styles.keyLabel("Used (looted)"));
        grid.add(usedLoot);
        Styles.capHeight(grid);
        card.add(grid);

        return card;
    }

    private JPanel xpCard() {
        JPanel card = Styles.card();
        xpBody.setBackground(Styles.CARD);
        xpBody.setAlignmentX(Component.LEFT_ALIGNMENT);
        card.add(xpBody);
        return card;
    }

    private JPanel killsCard() {
        JPanel card = Styles.card();
        killsBody.setBackground(Styles.CARD);
        killsBody.setAlignmentX(Component.LEFT_ALIGNMENT);
        card.add(killsBody);
        return card;
    }

    // What the kills/XP cards currently show. Rebuilding Swing rows every tick is wasteful and
    // the lists only change on a kill or an XP drop, so unchanged lists are left alone.
    private List<NpcKills> renderedKills;
    private List<SkillXp> renderedXp;
    private boolean killsRendered;
    private boolean xpRendered;

    private static boolean sameKills(List<NpcKills> a, List<NpcKills> b) {
        if (a == b) {
            return true;
        }
        if (a == null || b == null || a.size() != b.size()) {
            return false;
        }
        for (int i = 0; i < a.size(); i++) {
            if (a.get(i).count != b.get(i).count || !a.get(i).npc.equals(b.get(i).npc)) {
                return false;
            }
        }
        return true;
    }

    private static boolean sameXp(List<SkillXp> a, List<SkillXp> b) {
        if (a == b) {
            return true;
        }
        if (a == null || b == null || a.size() != b.size()) {
            return false;
        }
        for (int i = 0; i < a.size(); i++) {
            if (a.get(i).xp != b.get(i).xp || !a.get(i).skill.equals(b.get(i).skill)) {
                return false;
            }
        }
        return true;
    }

    private void renderKills(List<NpcKills> kills) {
        if (killsRendered && sameKills(kills, renderedKills)) {
            return;
        }
        killsRendered = true;
        renderedKills = kills;
        killsBody.removeAll();
        if (kills == null || kills.isEmpty()) {
            killsBody.add(Styles.keyLabel("None"));
            killsBody.add(new JLabel(""));
        } else {
            int total = 0;
            for (NpcKills k : kills) {
                total += k.count;
                killsBody.add(Styles.keyLabel(k.npc));
                JLabel v = Styles.valueLabel(Styles.TEXT);
                v.setText(Integer.toString(k.count));
                killsBody.add(v);
            }
            Styles.addBoldRow(killsBody, "Total", Integer.toString(total), Styles.TEXT);
        }
        Styles.capHeight(killsBody);
        killsBody.revalidate();
        killsBody.repaint();
    }

    private JPanel sessionCard() {
        JPanel card = Styles.card();
        JPanel grid = new JPanel(new GridLayout(0, 2, 0, 3));
        grid.setBackground(Styles.CARD);
        grid.setAlignmentX(Component.LEFT_ALIGNMENT);
        grid.add(Styles.keyLabel("Trips"));
        grid.add(sessTrips);
        grid.add(Styles.keyLabel("Net profit"));
        grid.add(sessNet);
        grid.add(Styles.keyLabel("Gathered"));
        grid.add(sessGathered);
        grid.add(Styles.keyLabel("Total XP"));
        grid.add(sessXp);
        grid.add(Styles.keyLabel("GP/hr"));
        grid.add(sessGpHr);
        Styles.capHeight(grid);
        card.add(grid);
        return card;
    }

    private void renderXp(List<SkillXp> xp) {
        if (xpRendered && sameXp(xp, renderedXp)) {
            return;
        }
        xpRendered = true;
        renderedXp = xp;
        xpBody.removeAll();
        if (xp == null || xp.isEmpty()) {
            xpBody.add(Styles.keyLabel("None"));
            xpBody.add(new JLabel(""));
        } else {
            long total = 0;
            for (SkillXp s : xp) {
                total += s.xp;
                xpBody.add(Styles.skillLabel(s.skill, skillIcons.get(s.skill)));
                JLabel v = Styles.valueLabel(Styles.XP);
                v.setText(GpFormat.format(s.xp));
                xpBody.add(v);
            }
            Styles.addBoldRow(xpBody, "Total", GpFormat.format(total), Styles.XP);
        }
        Styles.capHeight(xpBody);
        xpBody.revalidate();
        xpBody.repaint();
    }

    private JPanel buildDeathPrompt() {
        JLabel msg = new JLabel("<html>You died this trip — keep or discard it?</html>");
        msg.setForeground(Styles.MISSED);
        msg.setAlignmentX(Component.LEFT_ALIGNMENT);
        deathPrompt.add(msg);
        deathPrompt.add(Box.createVerticalStrut(6));
        JPanel pair = new JPanel(new GridLayout(1, 2, 5, 0));
        pair.setBackground(Styles.CARD);
        pair.setAlignmentX(Component.LEFT_ALIGNMENT);
        keepDeath.setForeground(Styles.GP);
        pair.add(keepDeath);
        pair.add(discardDeath);
        Styles.capHeight(pair);
        deathPrompt.add(pair);
        deathPrompt.setVisible(false);
        return deathPrompt;
    }

    private void onClient(Runnable r) {
        clientThread.invoke(r);
    }

    void setService(TrackingService service, boolean loggedIn) {
        this.service = service;
        this.loggedIn = loggedIn;
        render();
    }

    void showDeathPrompt() {
        deathPrompt.setVisible(true);
        renderControls();
    }

    void render() {
        renderControls();
        renderStats();
    }

    private void renderControls() {
        boolean tracking = service != null && service.isTracking();
        startStop.setEnabled(loggedIn && service != null);
        startStop.setText(tracking ? "Stop tracking" : "Start tracking");
        endTrip.setEnabled(tracking);
        discardTrip.setEnabled(tracking);
        // The session snapshot counts the current trip, so > 1 means a completed trip exists.
        boolean hasCompletedTrip = tracking
                && service.currentSessionSnapshot().map(s -> s.tripCount > 1).orElse(false);
        resumeTrip.setEnabled(hasCompletedTrip);
        if (!loggedIn) {
            status.setText("Log in to start tracking");
            statusDot.setForeground(Styles.SUBTEXT);
        } else if (tracking) {
            status.setText("Tracking");
            statusDot.setForeground(Styles.GP);
        } else {
            status.setText("Ready");
            statusDot.setForeground(Styles.MISSED);
        }
        if (service == null || !loggedIn) {
            deathPrompt.setVisible(false);
        }
    }

    private void renderStats() {
        Optional<TripSnapshot> snap = service == null ? Optional.empty() : service.currentSnapshot();
        if (snap.isPresent()) {
            TripSnapshot s = snap.get();
            setSigned(tripGpHr, s.gpPerHour);
            long xpHr = s.durationMillis > 0 ? s.totalXp * MILLIS_PER_HOUR / s.durationMillis : 0;
            tripXpHr.setText(GpFormat.format(xpHr));
            picked.setText(GpFormat.format(s.pickedGp));
            ground.setText(GpFormat.format(s.groundGp));
            supplies.setText(GpFormat.format(s.suppliesGp));
            gathered.setText(GpFormat.format(s.gatheredGp));
            usedLoot.setText(GpFormat.format(s.consumedLootGp));
            elapsed.setText(formatElapsed(s.durationMillis));
            renderXp(s.xpBySkill);
            renderKills(s.killsByNpc);
        } else {
            tripGpHr.setText("-");
            tripGpHr.setForeground(Styles.GP);
            tripXpHr.setText("-");
            picked.setText("-");
            ground.setText("-");
            supplies.setText("-");
            gathered.setText("-");
            usedLoot.setText("-");
            elapsed.setText("");
            renderXp(null);
            renderKills(null);
        }
        Optional<SessionSnapshot> sess = service == null ? Optional.empty() : service.currentSessionSnapshot();
        if (sess.isPresent()) {
            SessionSnapshot s = sess.get();
            sessTrips.setText(Integer.toString(s.tripCount));
            setSigned(sessNet, s.netProfit);
            sessGathered.setText(GpFormat.format(s.gatheredGp));
            sessXp.setText(GpFormat.format(s.totalXp));
            setSigned(sessGpHr, s.gpPerHour);
        } else {
            sessTrips.setText("-");
            sessNet.setText("-");
            sessNet.setForeground(Styles.GP);
            sessGathered.setText("-");
            sessXp.setText("-");
            sessGpHr.setText("-");
            sessGpHr.setForeground(Styles.GP);
        }
    }

    private static void setSigned(JLabel label, long value) {
        label.setText(GpFormat.format(value));
        label.setForeground(value < 0 ? Styles.NEG : Styles.GP);
    }

    private static String formatElapsed(long ms) {
        long totalSec = ms / 1000;
        long h = totalSec / 3600;
        long m = (totalSec % 3600) / 60;
        long s = totalSec % 60;
        return h > 0
                ? String.format("%d:%02d:%02d", h, m, s)
                : String.format("%d:%02d", m, s);
    }
}

package com.sessiontracker.adapter.runelite;

import com.sessiontracker.adapter.ChargedItems;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/**
 * Reads the plank sack's per-plank-type counts (one varbit each) and folds them into carried, so
 * filling the sack is net zero and building from it is a genuine plank decrease.
 */
public final class PlankSackReader {

    private static final int[] VARBITS = {
        VarbitID.PLANK_SACK_PLAIN,
        VarbitID.PLANK_SACK_OAK,
        VarbitID.PLANK_SACK_TEAK,
        VarbitID.PLANK_SACK_MAHOGANY,
        VarbitID.PLANK_SACK_CAMPHOR,
        VarbitID.PLANK_SACK_IRONWOOD,
        VarbitID.PLANK_SACK_ROSEWOOD,
    };
    private static final int[] ITEM_IDS = {
        ItemID.WOODPLANK,
        ItemID.PLANK_OAK,
        ItemID.PLANK_TEAK,
        ItemID.PLANK_MAHOGANY,
        ItemID.PLANK_CAMPHOR,
        ItemID.PLANK_IRONWOOD,
        ItemID.PLANK_ROSEWOOD,
    };

    private final Client client;

    public PlankSackReader(Client client) {
        this.client = client;
    }

    /** Current plank sack contents as plankItemId -&gt; quantity (empty if no sack or an empty one). */
    public Map<Integer, Integer> contents() {
        return ChargedItems.contents(VARBITS, ITEM_IDS, client::getVarbitValue);
    }

    /** True if {@code varbitId} is one of the plank sack count varbits. */
    public static boolean isPlankSackVarbit(int varbitId) {
        for (int v : VARBITS) {
            if (v == varbitId) {
                return true;
            }
        }
        return false;
    }
}

package com.sessiontracker.adapter.runelite;

import com.sessiontracker.adapter.RunePouch;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.Varbits;

/** Reads the rune pouch's slot varbits and resolves rune item ids via the game cache enum. */
public final class RunePouchReader {

    // The rune pouch's per-slot type varbit holds an index; this cache enum maps it to a rune
    // item id (the same enum RuneLite's own runepouch plugin reads).
    private static final int RUNE_POUCH_RUNE_ENUM = 982;

    private static final int[] TYPE_VARBITS = {
        Varbits.RUNE_POUCH_RUNE1, Varbits.RUNE_POUCH_RUNE2,
        Varbits.RUNE_POUCH_RUNE3, Varbits.RUNE_POUCH_RUNE4,
    };
    private static final int[] AMOUNT_VARBITS = {
        Varbits.RUNE_POUCH_AMOUNT1, Varbits.RUNE_POUCH_AMOUNT2,
        Varbits.RUNE_POUCH_AMOUNT3, Varbits.RUNE_POUCH_AMOUNT4,
    };

    private final Client client;

    public RunePouchReader(Client client) {
        this.client = client;
    }

    /** Current rune-pouch contents as runeItemId -&gt; quantity (empty if no pouch / empty pouch). */
    public Map<Integer, Integer> contents() {
        int[] types = new int[TYPE_VARBITS.length];
        int[] amounts = new int[AMOUNT_VARBITS.length];
        for (int i = 0; i < types.length; i++) {
            types[i] = client.getVarbitValue(TYPE_VARBITS[i]);
            amounts[i] = client.getVarbitValue(AMOUNT_VARBITS[i]);
        }
        return RunePouch.contents(types, amounts, this::itemIdForType);
    }

    private int itemIdForType(int typeValue) {
        if (typeValue <= 0) {
            return 0;
        }
        EnumComposition e = client.getEnum(RUNE_POUCH_RUNE_ENUM);
        return e == null ? 0 : e.getIntValue(typeValue);
    }

    /** True if {@code varbitId} is one of the rune-pouch slot varbits (type or amount). */
    public static boolean isRunePouchVarbit(int varbitId) {
        for (int v : TYPE_VARBITS) {
            if (v == varbitId) {
                return true;
            }
        }
        for (int v : AMOUNT_VARBITS) {
            if (v == varbitId) {
                return true;
            }
        }
        return false;
    }
}

