        Styles.clickable(row, () -> showDetail(sessionId, t.tripId));
        return row;
    }

    private JPanel editForm(SessionHistory.SessionSummary s) {
        JPanel form = Styles.card();

        JLabel nameKey = Styles.keyLabel("Name");
        nameKey.setAlignmentX(Component.LEFT_ALIGNMENT);
        JTextField name = new JTextField(s.name == null ? "" : s.name);
        styleField(name);
        form.add(nameKey);
        form.add(name);
        form.add(Box.createVerticalStrut(6));

        JLabel catKey = Styles.keyLabel("Category");
        catKey.setAlignmentX(Component.LEFT_ALIGNMENT);
        JTextField category = new JTextField(s.category == null ? "" : s.category);
        styleField(category);
        form.add(catKey);
        form.add(category);

        List<String> existing = history.categories();
        if (!existing.isEmpty()) {
            JPanel chips = new JPanel(new WrapLayout(FlowLayout.LEFT, 4, 4)) {
                @Override
                public Dimension getMaximumSize() {
                    return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
                }
            };
            chips.setBackground(Styles.CARD);
            chips.setBorder(new EmptyBorder(4, 0, 0, 0));
            chips.setAlignmentX(Component.LEFT_ALIGNMENT);
            for (String c : existing) {
                JButton chip = Styles.chip(c);
                chip.addActionListener(e -> category.setText(c));
                chips.add(chip);
            }
            form.add(chips);
        }
        form.add(Box.createVerticalStrut(8));

        JPanel buttons = new JPanel(new GridLayout(1, 2, 5, 0));
        buttons.setBackground(Styles.CARD);
        buttons.setAlignmentX(Component.LEFT_ALIGNMENT);
        JButton save = Styles.button("Save", Styles.ORANGE, Styles.PANEL);
        JButton cancel = Styles.button("Cancel", Styles.TILE, Styles.TEXT);
        save.addActionListener(e -> {
            String newName = name.getText();
            String newCat = category.getText().isEmpty() ? s.category : category.getText();
            applyEdit(s.sessionId, newName, newCat);
            editingSessionId = null;
            renderList();
        });
        cancel.addActionListener(e -> {
            editingSessionId = null;
            renderList();
        });
        buttons.add(save);
        buttons.add(cancel);
        Styles.capHeight(buttons);
        form.add(buttons);

        boolean isActive = service != null && s.sessionId.equals(service.activeSessionId());
        if (!isActive) {
            form.add(Box.createVerticalStrut(5));
            JButton delete = Styles.button("Delete session", Styles.NEG, Styles.PANEL);
            delete.setAlignmentX(Component.LEFT_ALIGNMENT);
            delete.addActionListener(e -> confirmAndDeleteSession(s.sessionId));
            Styles.capHeight(delete);
            form.add(delete);
        }
        return form;
    }

    private static void styleField(JTextField field) {
        field.setBackground(Styles.TILE);
        field.setForeground(Styles.TEXT);
        field.setCaretColor(Styles.TEXT);
        field.setFont(FontManager.getRunescapeSmallFont());
        field.setBorder(new EmptyBorder(4, 5, 4, 5));
        field.setAlignmentX(Component.LEFT_ALIGNMENT);
        Styles.capHeight(field);
    }

    private void applyEdit(String sessionId, String newName, String newCategory) {
        boolean isActive = service != null && sessionId.equals(service.activeSessionId());
        if (isActive) {
            clientThread.invoke(() -> {
                service.renameActiveSession(newName);
                service.recategorizeActiveSession(newCategory);
            });
        } else {
            history.rename(sessionId, newName);
            history.recategorize(sessionId, newCategory);
        }
    }

    private void confirmAndDeleteSession(String sessionId) {
        if (service != null && sessionId.equals(service.activeSessionId())) {
            return; // never delete the in-progress session
        }
        int choice = JOptionPane.showConfirmDialog(this,
                "Delete this session? This cannot be undone.",
                "Delete session", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
        if (choice != JOptionPane.YES_OPTION) {
            return;
        }
        history.deleteSession(sessionId);
        editingSessionId = null;
        expandedSessionId = null;
        reload();
    }

    private void confirmAndDeleteTrip(String sessionId, String tripId) {
        int choice = JOptionPane.showConfirmDialog(this,
                "Delete this trip? This cannot be undone.",
                "Delete trip", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
        if (choice != JOptionPane.YES_OPTION) {
            return;
        }
        editingSessionId = null;
        expandedSessionId = null;
        if (service != null && sessionId.equals(service.activeSessionId())) {
            // The running session owns its trips: it drops the trip, recomputes and saves.
            clientThread.invoke(() -> {
                service.deleteCompletedTrip(tripId);
                SwingUtilities.invokeLater(this::reload);
            });
        } else {
            history.deleteTrip(sessionId, tripId);
            reload();
        }
    }

    private void resumeSession(String sessionId) {
        if (service == null) {
            return;
        }
        editingSessionId = null;
        expandedSessionId = sessionId;
        clientThread.invoke(() -> {
            service.resumeSession(sessionId);
            SwingUtilities.invokeLater(this::reload);
        });
    }

    private void showDetail(String sessionId, String tripId) {
        clientThread.invoke(() -> {
            SessionHistory.TripDetail d = history.tripDetail(sessionId, tripId);
            SwingUtilities.invokeLater(() -> renderDetail(sessionId, tripId, d));
        });
    }

    private void renderDetail(String sessionId, String tripId, SessionHistory.TripDetail d) {
        detailBody.removeAll();

        JButton back = Styles.linkButton("Back", Styles.ORANGE);
        back.setIcon(Styles.caret(Styles.CARET_LEFT, Styles.ORANGE));
        back.setIconTextGap(5);
        back.addActionListener(e -> cards.show(root, LIST));

        JPanel topBar = new JPanel(new BorderLayout());
        topBar.setBackground(Styles.PANEL);
        topBar.setAlignmentX(Component.LEFT_ALIGNMENT);
        topBar.add(back, BorderLayout.WEST);
        JButton delete = Styles.linkButton("Delete trip", Styles.NEG);
        delete.addActionListener(e -> confirmAndDeleteTrip(sessionId, tripId));
        topBar.add(delete, BorderLayout.EAST);
        Styles.capHeight(topBar);
        detailBody.add(topBar);
        detailBody.add(Box.createVerticalStrut(6));

        if (d != null) {
            JPanel summary = Styles.card();
            JPanel grid = new JPanel(new GridLayout(0, 2, 0, 3));
            grid.setBackground(Styles.CARD);
            grid.setAlignmentX(Component.LEFT_ALIGNMENT);
            grid.add(Styles.keyLabel("Net profit"));
            grid.add(signedValue(d.netProfit));
            grid.add(Styles.keyLabel("Missed"));
            JLabel missed = Styles.valueLabel(Styles.MISSED);
            missed.setText(GpFormat.format(d.missedValue));
            grid.add(missed);
            grid.add(Styles.keyLabel("Duration"));
            JLabel duration = Styles.valueLabel(Styles.TEXT);
            duration.setText(DurationFormat.compact(d.durationMillis));
            grid.add(duration);
            Styles.capHeight(grid);
            summary.add(grid);
            detailBody.add(summary);

            addKillsGroup(d.killsByNpc);

            addGroup("Picked up", d.pickedUp, Styles.GP);
            addGroup("Gathered", d.gathered, Styles.GP);
            addGroup("Used loot", d.usedLoot, Styles.TEXT);
            addGroup("Left on ground", d.leftOnGround, Styles.MISSED);
            addGroup("Supplies used", d.suppliesUsed, Styles.NEG);
            addXpGroup(d.xpGained);
        }
        detailBody.revalidate();
        detailBody.repaint();
        cards.show(root, DETAIL);
    }

    private void addKillsGroup(List<NpcKills> kills) {
        detailBody.add(Styles.sectionHeader("Kills"));
        JPanel card = Styles.card();
        if (kills == null || kills.isEmpty()) {
            JLabel none = Styles.keyLabel("None");
            none.setAlignmentX(Component.LEFT_ALIGNMENT);
            card.add(none);
        } else {
            JPanel grid = new JPanel(new GridLayout(0, 2, 0, 3));
            grid.setBackground(Styles.CARD);
            grid.setAlignmentX(Component.LEFT_ALIGNMENT);
            int total = 0;
            for (NpcKills k : kills) {
                total += k.count;
                JLabel npc = Styles.keyLabel(k.npc);
                npc.setToolTipText(k.npc);
                grid.add(npc);
                JLabel v = Styles.valueLabel(Styles.TEXT);
                v.setText(Integer.toString(k.count));
                grid.add(v);
            }
            Styles.addBoldRow(grid, "Total", Integer.toString(total), Styles.TEXT);
            Styles.capHeight(grid);
            card.add(grid);
        }
        detailBody.add(card);
    }

    private void addXpGroup(List<SkillXp> xp) {
        detailBody.add(Styles.sectionHeader("XP gained"));
        JPanel card = Styles.card();
        if (xp == null || xp.isEmpty()) {
            JLabel none = Styles.keyLabel("None");
            none.setAlignmentX(Component.LEFT_ALIGNMENT);
            card.add(none);
        } else {
            JPanel grid = new JPanel(new GridLayout(0, 2, 0, 3));
            grid.setBackground(Styles.CARD);
            grid.setAlignmentX(Component.LEFT_ALIGNMENT);
            long total = 0;
            for (SkillXp s : xp) {
                total += s.xp;
                JLabel skill = Styles.skillLabel(s.skill, skillIcons.get(s.skill));
                skill.setToolTipText(s.skill);
                grid.add(skill);
                JLabel v = Styles.valueLabel(Styles.XP);
                v.setText(GpFormat.format(s.xp));
                grid.add(v);
            }
            Styles.addBoldRow(grid, "Total", GpFormat.format(total), Styles.XP);
            Styles.capHeight(grid);
            card.add(grid);
        }
        detailBody.add(card);
    }

    private void addGroup(String title, List<SessionHistory.ItemLine> lines, java.awt.Color valueColor) {
        detailBody.add(Styles.sectionHeader(title));
        JPanel card = Styles.card();
        if (lines.isEmpty()) {
            JLabel none = Styles.keyLabel("None");
            none.setAlignmentX(Component.LEFT_ALIGNMENT);
            card.add(none);
        } else if (itemIcons.enabled()) {
            card.add(iconGrid(lines));
        } else {
            JPanel grid = new JPanel(new GridLayout(0, 2, 0, 3));
            grid.setBackground(Styles.CARD);
            grid.setAlignmentX(Component.LEFT_ALIGNMENT);
            for (SessionHistory.ItemLine l : lines) {
                JLabel k = Styles.keyLabel(l.label + " ×" + l.quantity);
                k.setToolTipText(Styles.itemTooltip(l.label, l.quantity, l.isPotion, l.dosesPerPotion));
                grid.add(k);
                JLabel v = Styles.valueLabel(valueColor);
                v.setText(GpFormat.format(l.gpValue));
                grid.add(v);
            }
            Styles.capHeight(grid);
            card.add(grid);
        }
        detailBody.add(card);
    }

    /** Item lines as an inventory-style grid: sprite plus count, with the detail in the tooltip. */
    private JPanel iconGrid(List<SessionHistory.ItemLine> lines) {
        JPanel grid = Styles.iconGrid();
        for (SessionHistory.ItemLine l : lines) {
            String qty = StackText.count(l.quantity);
            String tip = Styles.itemCellTooltip(l.label, qty, l.quantity, l.gpValue,
                    l.isPotion, l.dosesPerPotion);
            if (l.iconItemId == null) {
                grid.add(Styles.textChip(l.label + " ×" + qty, tip));
            } else {
                JLabel cell = Styles.iconCell(tip);
                itemIcons.apply(cell, l.iconItemId, qty);
                grid.add(cell);
            }
        }
        return grid;
    }

    private JPanel sessionSummaryCard(SessionHistory.SessionSummary s) {
        JPanel card = Styles.card();

        JLabel gp = new JLabel(GpFormat.format(s.gpPerHour));
        JLabel xp = new JLabel(GpFormat.format(s.xpPerHour));
        JPanel tiles = new JPanel(new GridLayout(1, 2, 6, 0));
        tiles.setBackground(Styles.CARD);
        tiles.setAlignmentX(Component.LEFT_ALIGNMENT);
        tiles.add(Styles.tile(gp, "GP/hr", s.gpPerHour < 0 ? Styles.NEG : Styles.GP));
        tiles.add(Styles.tile(xp, "XP/hr", Styles.XP));
        Styles.capHeight(tiles);
        card.add(tiles);
        card.add(Box.createVerticalStrut(6));

        JPanel grid = new JPanel(new GridLayout(0, 2, 0, 3));
        grid.setBackground(Styles.CARD);
        grid.setAlignmentX(Component.LEFT_ALIGNMENT);
        grid.add(Styles.keyLabel("Duration"));
        JLabel duration = Styles.valueLabel(Styles.TEXT);
        duration.setText(DurationFormat.compact(s.wallClockMillis));
        grid.add(duration);
        grid.add(Styles.keyLabel("Avg net / trip"));
        grid.add(signedValue(s.avgNetProfitPerTrip));
        grid.add(Styles.keyLabel("Avg XP / trip"));
        JLabel avgXp = Styles.valueLabel(Styles.XP);
        avgXp.setText(GpFormat.format(s.avgXpPerTrip));
        grid.add(avgXp);
        grid.add(Styles.keyLabel("Avg kills / trip"));
        JLabel avgKills = Styles.valueLabel(Styles.TEXT);
        avgKills.setText(String.format(java.util.Locale.US, "%.1f", s.avgKillsPerTrip));
        grid.add(avgKills);
        Styles.capHeight(grid);
        card.add(grid);

        boolean isActive = service != null && s.sessionId.equals(service.activeSessionId());
        if (service != null && !isActive) {
            card.add(Box.createVerticalStrut(6));
            JButton resume = Styles.button("Resume session", Styles.ORANGE, Styles.PANEL);
            resume.setToolTipText("Continue this session: new trips are added to it and the "
                    + "time since it ended is not counted");
            resume.setAlignmentX(Component.LEFT_ALIGNMENT);
            resume.addActionListener(e -> resumeSession(s.sessionId));
            Styles.capHeight(resume);
            card.add(resume);
        }

        return card;
    }

    private static JLabel signedValue(long value) {
        JLabel l = Styles.valueLabel(value < 0 ? Styles.NEG : Styles.GP);
        l.setText(GpFormat.format(value));
        return l;
    }
}

package com.sessiontracker.adapter.runelite;

import com.sessiontracker.adapter.StashMatcher;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.OptionalInt;
import net.runelite.api.gameval.ItemID;

/**
 * The storage containers whose contents the client cannot read, and the message the game prints
 * as each one swallows something you gathered.
 *
 * <p>An item only reaches these containers while they are open, and open is a different item id
 * from closed, so the open ids are what decide whether a message counts. The keyword for each
 * item is the word the message uses, which is not always the item's own name: the herb sack says
 * "Grimy ranarr herb" for an item called "Grimy ranarr weed".
 */
final class StashBags {

    /** One container: what it is called, which item ids are it, and what its messages mean. */
    static final class Bag {
        private final String name;
        private final int[] openIds;
        private final int[] closedIds;
        private final StashMatcher matcher;

        Bag(String name, int[] openIds, int[] closedIds, StashMatcher matcher) {
            this.name = name;
            this.openIds = openIds;
            this.closedIds = closedIds;
            this.matcher = matcher;
        }

        String name() {
            return name;
        }

        /** The item this message says was swallowed, if it is one this container holds. */
        OptionalInt match(String message) {
            return matcher.match(message);
        }

        boolean isOpen(int itemId) {
            return contains(openIds, itemId);
        }

        boolean isAnyForm(int itemId) {
            return contains(openIds, itemId) || contains(closedIds, itemId);
        }
    }

    private static boolean contains(int[] ids, int itemId) {
        for (int id : ids) {
            if (id == itemId) {
                return true;
            }
        }
        return false;
    }

    private static Map<String, Integer> keywords(Object... pairs) {
        Map<String, Integer> m = new HashMap<>();
        for (int i = 0; i < pairs.length; i += 2) {
            m.put((String) pairs[i], (Integer) pairs[i + 1]);
        }
        return m;
    }

    // "You manage to mine some coal."
    private static final StashMatcher COAL = new StashMatcher(
            "^you manage to mine some .+\\.$",
            keywords("coal", ItemID.COAL));

    // "You just found a Sapphire!" / "You just mined a piece of Jade!"
    private static final StashMatcher GEMS = new StashMatcher(
            "^you just (found|mined) (a|an|a piece of) .+!$",
            keywords(
                    "sapphire", ItemID.UNCUT_SAPPHIRE,
                    "emerald", ItemID.UNCUT_EMERALD,
                    "ruby", ItemID.UNCUT_RUBY,
                    "diamond", ItemID.UNCUT_DIAMOND,
                    "dragonstone", ItemID.UNCUT_DRAGONSTONE,
                    "opal", ItemID.UNCUT_OPAL,
                    "jade", ItemID.UNCUT_JADE,
                    "red topaz", ItemID.UNCUT_RED_TOPAZ));

    // "You put the Grimy ranarr herb into your herb sack."
    private static final StashMatcher HERBS = new StashMatcher(
            "^you put the .+ into your herb sack\\.$",
            keywords(
                    "guam", ItemID.UNIDENTIFIED_GUAM,
                    "marrentill", ItemID.UNIDENTIFIED_MARENTILL,
                    "tarromin", ItemID.UNIDENTIFIED_TARROMIN,
                    "harralander", ItemID.UNIDENTIFIED_HARRALANDER,
                    "ranarr", ItemID.UNIDENTIFIED_RANARR,
                    "toadflax", ItemID.UNIDENTIFIED_TOADFLAX,
                    "irit", ItemID.UNIDENTIFIED_IRIT,
                    "avantoe", ItemID.UNIDENTIFIED_AVANTOE,
                    "kwuarm", ItemID.UNIDENTIFIED_KWUARM,
                    "snapdragon", ItemID.UNIDENTIFIED_SNAPDRAGON,
                    "cadantine", ItemID.UNIDENTIFIED_CADANTINE,
                    "lantadyme", ItemID.UNIDENTIFIED_LANTADYME,
                    "dwarf weed", ItemID.UNIDENTIFIED_DWARF_WEED,
                    "torstol", ItemID.UNIDENTIFIED_TORSTOL,
                    "huasca", ItemID.UNIDENTIFIED_HUASCA));

    // "You catch a shark." / "You catch some anchovies."
    private static final StashMatcher FISH = new StashMatcher(
            "^you catch (a|an|some) .+[.!]$",
            keywords(
                    "shrimp", ItemID.RAW_SHRIMP,
                    "anchovies", ItemID.RAW_ANCHOVIES,
                    "sardine", ItemID.RAW_SARDINE,
                    "salmon", ItemID.RAW_SALMON,
                    "trout", ItemID.RAW_TROUT,
                    "cod", ItemID.RAW_COD,
                    "herring", ItemID.RAW_HERRING,
                    "pike", ItemID.RAW_PIKE,
                    "mackerel", ItemID.RAW_MACKEREL,
                    "tuna", ItemID.RAW_TUNA,
                    "bass", ItemID.RAW_BASS,
                    "swordfish", ItemID.RAW_SWORDFISH,
                    "lobster", ItemID.RAW_LOBSTER,
                    "shark", ItemID.RAW_SHARK,
                    "manta ray", ItemID.RAW_MANTARAY,
                    "sea turtle", ItemID.RAW_SEATURTLE,
                    "monkfish", ItemID.RAW_MONKFISH,
                    "anglerfish", ItemID.RAW_ANGLERFISH,
                    "dark crab", ItemID.RAW_DARK_CRAB));

    // "You get some yew logs."
    private static final StashMatcher LOGS = new StashMatcher(
            "^you get some .+\\.$",
            keywords(
                    "logs", ItemID.LOGS,
                    "oak logs", ItemID.OAK_LOGS,
                    "willow logs", ItemID.WILLOW_LOGS,
                    "teak logs", ItemID.TEAK_LOGS,
                    "maple logs", ItemID.MAPLE_LOGS,
                    "mahogany logs", ItemID.MAHOGANY_LOGS,
                    "yew logs", ItemID.YEW_LOGS,
                    "magic logs", ItemID.MAGIC_LOGS,
                    "redwood logs", ItemID.REDWOOD_LOGS));

    private static final List<Bag> BAGS = Collections.unmodifiableList(Arrays.asList(
            new Bag("coal bag",
                    new int[]{ItemID.COAL_BAG_OPEN},
                    new int[]{ItemID.COAL_BAG}, COAL),
            new Bag("gem bag",
                    new int[]{ItemID.GEM_BAG_OPEN, ItemID.GEM_SACK_OPEN},
                    new int[]{ItemID.GEM_BAG, ItemID.GEM_SACK}, GEMS),
            new Bag("herb sack",
                    new int[]{ItemID.SLAYER_HERB_SACK_OPEN, ItemID.SLAYER_HERB_SACK_SILK_OPEN},
                    new int[]{ItemID.SLAYER_HERB_SACK, ItemID.SLAYER_HERB_SACK_SILK}, HERBS),
            new Bag("fish barrel",
                    new int[]{ItemID.FISH_BARREL_OPEN, ItemID.FISH_SACK_BARREL_OPEN},
                    new int[]{ItemID.FISH_BARREL_CLOSED, ItemID.FISH_SACK_BARREL_CLOSED}, FISH),
            new Bag("log basket",
                    new int[]{ItemID.LOG_BASKET_OPEN, ItemID.FORESTRY_BASKET_OPEN},
                    new int[]{ItemID.LOG_BASKET_CLOSED, ItemID.FORESTRY_BASKET_CLOSED}, LOGS)));

    private StashBags() {
    }

    static List<Bag> all() {
        return BAGS;
    }

    /** The container this item id is, but only in its open form, which is the one that collects. */
    static Optional<Bag> byOpenItemId(int itemId) {
        for (Bag bag : BAGS) {
            if (bag.isOpen(itemId)) {
                return Optional.of(bag);
            }
        }
        return Optional.empty();
    }

    /** The container this item id is, open or closed, for forgetting it after a manual transfer. */
    static Optional<Bag> byAnyItemId(int itemId) {
        for (Bag bag : BAGS) {
            if (bag.isAnyForm(itemId)) {
                return Optional.of(bag);
            }
        }
        return Optional.empty();
    }
}

package com.sessiontracker.adapter.runelite;

import net.runelite.api.gameval.ItemID;

/**
 * Storage containers whose contents the client cannot read: herb sack, gem bag, coal bag, fish
 * barrel, fish sack barrel and log basket (plus the readable ones, for which this is a harmless
 * belt-and-braces). Their contents never appear in any item container or varbit, so the only
 * signal is the player's own <b>Fill</b> / <b>Empty</b> action on the item. The plugin uses that
 * click to treat the inventory change that follows as a move rather than a consumption or a gain.
 */
public final class StashContainers {

    private static final int[] ITEM_IDS = {
        ItemID.SLAYER_HERB_SACK, ItemID.SLAYER_HERB_SACK_OPEN,
        ItemID.SLAYER_HERB_SACK_SILK, ItemID.SLAYER_HERB_SACK_SILK_OPEN,
        ItemID.GEM_BAG, ItemID.GEM_BAG_OPEN,
        ItemID.COAL_BAG, ItemID.COAL_BAG_OPEN,
        ItemID.FISH_BARREL_CLOSED, ItemID.FISH_BARREL_OPEN,
        ItemID.FISH_SACK_BARREL_CLOSED, ItemID.FISH_SACK_BARREL_OPEN,
        ItemID.LOG_BASKET_CLOSED, ItemID.LOG_BASKET_OPEN,
        ItemID.SEED_BOX, ItemID.SEED_BOX_OPEN,
        ItemID.PLANK_SACK,
    };

    private StashContainers() {
    }

    /** True if clicking {@code option} on item {@code itemId} moves items into or out of a stash. */
    public static boolean isTransfer(int itemId, String option) {
        if (!"Fill".equals(option) && !"Empty".equals(option)) {
            return false;
        }
        for (int id : ITEM_IDS) {
            if (id == itemId) {
                return true;
            }
        }
        return false;
    }
}

package com.sessiontracker.adapter.runelite;

import com.sessiontracker.adapter.DurationFormat;
import com.sessiontracker.adapter.GpFormat;
import com.sessiontracker.adapter.SessionHistory;
import com.sessiontracker.adapter.StackText;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.GridLayout;
import java.util.List;
import java.util.Locale;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.FontManager;

/** Per-category stats: GP/hr-sorted cards, drill-in to averages + exact supply breakdown. */
final class StatsTab extends JPanel {

    private static final String CARDS = "cards";
    private static final String DETAIL = "detail";

    private final ClientThread clientThread;
    private final ItemIconProvider itemIcons;
    private final CardLayout cards = new CardLayout();
    private final JPanel root = new JPanel();
    private final JPanel cardsBody = new JPanel();
    private final JPanel detailBody = new JPanel();

    private SessionHistory history;

    StatsTab(ClientThread clientThread, ItemIconProvider itemIcons) {
        this.clientThread = clientThread;
        this.itemIcons = itemIcons;
        setBackground(Styles.PANEL);
        setLayout(new BorderLayout());
        root.setLayout(cards);
        root.setBackground(Styles.PANEL);
        cardsBody.setLayout(new BoxLayout(cardsBody, BoxLayout.Y_AXIS));
        cardsBody.setBackground(Styles.PANEL);
        cardsBody.setBorder(new EmptyBorder(8, 8, 8, 8));
        detailBody.setLayout(new BoxLayout(detailBody, BoxLayout.Y_AXIS));
        detailBody.setBackground(Styles.PANEL);
        detailBody.setBorder(new EmptyBorder(8, 8, 8, 8));
        root.add(wrapNorth(cardsBody), CARDS);
        root.add(wrapNorth(detailBody), DETAIL);
        add(root, BorderLayout.CENTER);
        cards.show(root, CARDS);
    }

    private static JPanel wrapNorth(JPanel inner) {
        JPanel p = new JPanel(new BorderLayout());
        p.setBackground(Styles.PANEL);
        p.add(inner, BorderLayout.NORTH);
        return p;
    }

    void setHistory(SessionHistory history) {
        this.history = history;
        reload();
    }

    void reload() {
        cardsBody.removeAll();
        if (history == null) {
            cardsBody.add(Styles.keyLabel("Log in to view stats"));
        } else {
            List<SessionHistory.CategoryStatsView> stats = history.categoryStats();
            if (stats.isEmpty()) {
                cardsBody.add(Styles.keyLabel("No sessions yet"));
            }
            for (SessionHistory.CategoryStatsView c : stats) {
                cardsBody.add(categoryCard(c));
                cardsBody.add(Box.createVerticalStrut(5));
            }
        }
        cardsBody.revalidate();
        cardsBody.repaint();
        cards.show(root, CARDS);
    }

    private JPanel categoryCard(SessionHistory.CategoryStatsView c) {
        JPanel card = Styles.card();

        JPanel header = new JPanel(new BorderLayout());
        header.setBackground(Styles.CARD);
        header.setAlignmentX(Component.LEFT_ALIGNMENT);
        JLabel name = new JLabel(c.category);
        name.setToolTipText(c.category);
        name.setFont(FontManager.getRunescapeBoldFont());
        name.setForeground(Styles.TEXT);
        header.add(name, BorderLayout.CENTER);
        header.add(new JLabel(Styles.caret(Styles.CARET_RIGHT, Styles.SUBTEXT)), BorderLayout.EAST);
        Styles.capHeight(header);
        card.add(header);

        String sessionWord = c.sessionCount == 1 ? "session" : "sessions";
        String tripWord = c.tripCount == 1 ? "trip" : "trips";
        JLabel meta = Styles.keyLabel(c.sessionCount + " " + sessionWord + " · " + c.tripCount + " " + tripWord);
        meta.setAlignmentX(Component.LEFT_ALIGNMENT);
        card.add(meta);
        card.add(Box.createVerticalStrut(6));

        card.add(tiles(c.gpPerHour, c.xpPerHour));

        Styles.clickable(card, () -> showDetail(c.category));
        return card;
    }

    /** A GP/hr (green, sign-aware) + XP/hr (blue) tile pair. */
    private static JPanel tiles(long gpPerHour, long xpPerHour) {
        JLabel gp = new JLabel(GpFormat.format(gpPerHour));
        JLabel xp = new JLabel(GpFormat.format(xpPerHour));
        JPanel row = new JPanel(new GridLayout(1, 2, 6, 0));
        row.setBackground(Styles.CARD);
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.add(Styles.tile(gp, "GP/hr", gpPerHour < 0 ? Styles.NEG : Styles.GP));
        row.add(Styles.tile(xp, "XP/hr", Styles.XP));
        Styles.capHeight(row);
        return row;
    }

    private void showDetail(String category) {
        clientThread.invoke(() -> {
            SessionHistory.CategoryDetail d = history.categoryDetail(category);
            SwingUtilities.invokeLater(() -> renderDetail(category, d));
        });
    }

    private void renderDetail(String category, SessionHistory.CategoryDetail d) {
        detailBody.removeAll();

        JButton back = Styles.linkButton("Back", Styles.ORANGE);
        back.setIcon(Styles.caret(Styles.CARET_LEFT, Styles.ORANGE));
        back.setIconTextGap(5);
        back.setAlignmentX(Component.LEFT_ALIGNMENT);
        back.addActionListener(e -> cards.show(root, CARDS));
        detailBody.add(back);
        detailBody.add(Box.createVerticalStrut(6));

        JLabel name = new JLabel(category);
        name.setToolTipText(category);
        name.setFont(FontManager.getRunescapeBoldFont());
        name.setForeground(Styles.TEXT);
        name.setAlignmentX(Component.LEFT_ALIGNMENT);
        detailBody.add(name);
        detailBody.add(Box.createVerticalStrut(4));
        detailBody.add(tiles(d.gpPerHour, d.xpPerHour));

        detailBody.add(Styles.sectionHeader("Per hour"));
        JPanel perHourCard = Styles.card();
        JPanel perHour = grid();
        perHour.add(Styles.keyLabel("Combat GP/hr"));
        perHour.add(signedValue(d.combatGpPerHour));
        perHour.add(Styles.keyLabel("Gather GP/hr"));
        perHour.add(signedValue(d.gatherGpPerHour));
        perHour.add(Styles.keyLabel("Supplies GP/hr"));
        JLabel supHr = Styles.valueLabel(Styles.NEG);
        supHr.setText(GpFormat.format(d.suppliesGpPerHour));
        perHour.add(supHr);
        Styles.capHeight(perHour);
        perHourCard.add(perHour);
        detailBody.add(perHourCard);

        detailBody.add(Styles.sectionHeader("Per-trip averages"));
        JPanel avgCard = Styles.card();
        JPanel avg = grid();
        avg.add(Styles.keyLabel("Net profit"));
        avg.add(signedValue(d.avgNetProfitPerTrip));
        avg.add(Styles.keyLabel("Missed"));
        JLabel missed = Styles.valueLabel(Styles.MISSED);
        missed.setText(GpFormat.format(d.avgMissedPerTrip));
        avg.add(missed);
        avg.add(Styles.keyLabel("Trip length"));
        JLabel len = Styles.valueLabel(Styles.TEXT);
        len.setText(DurationFormat.compact(d.avgTripDurationMillis));
        avg.add(len);
        avg.add(Styles.keyLabel("Kills"));
        JLabel kills = Styles.valueLabel(Styles.TEXT);
        kills.setText(String.format(Locale.US, "%.1f", d.avgKillsPerTrip));
        avg.add(kills);
        Styles.capHeight(avg);
        avgCard.add(avg);
        detailBody.add(avgCard);

        detailBody.add(Styles.sectionHeader("Per session"));
        JPanel sessionCard = Styles.card();
        JPanel sessionGrid = grid();
        sessionGrid.add(Styles.keyLabel("Avg session length"));
        JLabel sessionLen = Styles.valueLabel(Styles.TEXT);
        sessionLen.setText(DurationFormat.compact(d.avgSessionDurationMillis));
        sessionGrid.add(sessionLen);
        Styles.capHeight(sessionGrid);
        sessionCard.add(sessionGrid);
        detailBody.add(sessionCard);

        addItemTable("Avg picked up / trip", d.pickedAverages, d.avgPickedGpPerTrip, Styles.GP);
        addItemTable("Avg gathered / trip", d.gatheredAverages, d.avgGatheredGpPerTrip, Styles.GP);
        addItemTable("Avg used loot / trip", d.usedLootAverages, d.avgUsedLootGpPerTrip, Styles.TEXT);
        addItemTable("Avg supplies / trip", d.supplies, d.avgTotalSuppliesGpPerTrip, Styles.NEG);
        addItemTable("Avg left on ground / trip", d.missedAverages, d.avgMissedPerTrip, Styles.MISSED);
        addItemTable("Gross avg drops / trip", d.droppedAverages, d.avgDroppedGpPerTrip, Styles.TEXT);

        detailBody.add(Styles.sectionHeader("XP averages"));
        JPanel xpCard = Styles.card();
        if (d.xpAverages.isEmpty()) {
            JLabel none = Styles.keyLabel("None");
            none.setAlignmentX(Component.LEFT_ALIGNMENT);
            xpCard.add(none);
        } else {
            JPanel xpGrid = new JPanel(new GridLayout(0, 3, 6, 3));
            xpGrid.setBackground(Styles.CARD);
            xpGrid.setAlignmentX(Component.LEFT_ALIGNMENT);
            xpGrid.add(Styles.keyLabel("Skill"));
            xpGrid.add(rightValue("/trip", Styles.SUBTEXT));
            xpGrid.add(rightValue("/hr", Styles.SUBTEXT));
            long totalAvgTrip = 0;
            for (SessionHistory.SkillXpAverage a : d.xpAverages) {
                totalAvgTrip += a.avgXpPerTrip;
                JLabel skill = Styles.keyLabel(a.skill);
                skill.setToolTipText(a.skill);
                xpGrid.add(skill);
                xpGrid.add(rightValue(GpFormat.format(a.avgXpPerTrip), Styles.XP));
                xpGrid.add(rightValue(GpFormat.format(a.xpPerHour), Styles.XP));
            }
            xpGrid.add(boldLabel("Total", Styles.TEXT, SwingConstants.LEADING));
            xpGrid.add(boldLabel(GpFormat.format(totalAvgTrip), Styles.XP, SwingConstants.RIGHT));
            xpGrid.add(boldLabel(GpFormat.format(d.xpPerHour), Styles.XP, SwingConstants.RIGHT));
            Styles.capHeight(xpGrid);
            xpCard.add(xpGrid);
        }
        detailBody.add(xpCard);

        detailBody.add(Styles.sectionHeader("Kill averages"));
        JPanel killCard = Styles.card();
        if (d.killAverages.isEmpty()) {
            JLabel none = Styles.keyLabel("None");
            none.setAlignmentX(Component.LEFT_ALIGNMENT);
            killCard.add(none);
        } else {
            JPanel killGrid = new JPanel(new GridLayout(0, 3, 6, 3));
            killGrid.setBackground(Styles.CARD);
            killGrid.setAlignmentX(Component.LEFT_ALIGNMENT);
            killGrid.add(Styles.keyLabel("NPC"));
            killGrid.add(rightValue("/trip", Styles.SUBTEXT));
            killGrid.add(rightValue("/hr", Styles.SUBTEXT));
            double totalTrip = 0;
            double totalHr = 0;
            for (SessionHistory.NpcKillAverage k : d.killAverages) {
                totalTrip += k.avgPerTrip;
                totalHr += k.perHour;
                JLabel npc = Styles.keyLabel(k.npc);
                npc.setToolTipText(k.npc);
                killGrid.add(npc);
                killGrid.add(rightValue(String.format(Locale.US, "%.1f", k.avgPerTrip), Styles.TEXT));
                killGrid.add(rightValue(String.format(Locale.US, "%.1f", k.perHour), Styles.TEXT));
            }
            killGrid.add(boldLabel("Total", Styles.TEXT, SwingConstants.LEADING));
            killGrid.add(boldLabel(String.format(Locale.US, "%.1f", totalTrip), Styles.TEXT, SwingConstants.RIGHT));
            killGrid.add(boldLabel(String.format(Locale.US, "%.1f", totalHr), Styles.TEXT, SwingConstants.RIGHT));
            Styles.capHeight(killGrid);
            killCard.add(killGrid);
        }
        detailBody.add(killCard);

        detailBody.revalidate();
        detailBody.repaint();
        cards.show(root, DETAIL);
    }

    /**
     * A collapsible item-average section. The per-trip total sits (bold) in the clickable
     * header; the individual item rows stay hidden until the header is expanded, so the
     * detail view isn't bloated at first viewing.
     */
    private void addItemTable(String header, List<SessionHistory.ItemAverage> items,
                              long total, Color valueColor) {
        JPanel content = Styles.card();
        if (items.isEmpty()) {
            JLabel none = Styles.keyLabel("None");
            none.setAlignmentX(Component.LEFT_ALIGNMENT);
            content.add(none);
        } else if (itemIcons.enabled()) {
            content.add(iconGrid(items));
        } else {
            JPanel g = grid();
            for (SessionHistory.ItemAverage a : items) {
                JLabel k = Styles.keyLabel(a.label + "  " + String.format(Locale.US, "%.1f", a.avgQtyPerTrip));
                k.setToolTipText(Styles.itemTooltip(a.label, a.avgQtyPerTrip, a.isPotion, a.dosesPerPotion));
                g.add(k);
                JLabel v = Styles.valueLabel(valueColor);
                v.setText(GpFormat.format(a.avgGpPerTrip));
                g.add(v);
            }
            Styles.capHeight(g);
            content.add(g);
        }
        content.setVisible(false);

        JLabel caretIcon = new JLabel(Styles.caret(Styles.CARET_RIGHT, Styles.SUBTEXT));
        JLabel title = new JLabel(header);
        title.setFont(FontManager.getRunescapeSmallFont());
        title.setForeground(Styles.TEXT);
        JPanel left = new JPanel();
        left.setLayout(new BoxLayout(left, BoxLayout.X_AXIS));
        left.setBackground(Styles.CARD);
        left.add(caretIcon);
        left.add(Box.createHorizontalStrut(6));
        left.add(title);

        JPanel headerRow = new JPanel(new BorderLayout(6, 0));
        headerRow.setBackground(Styles.CARD);
        headerRow.setBorder(new EmptyBorder(6, 9, 6, 9));
        headerRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        headerRow.add(left, BorderLayout.WEST);
        headerRow.add(boldLabel(GpFormat.format(total), valueColor, SwingConstants.RIGHT), BorderLayout.EAST);
        Styles.capHeight(headerRow);

        Styles.clickable(headerRow, () -> {
            boolean show = !content.isVisible();
            content.setVisible(show);
            caretIcon.setIcon(Styles.caret(show ? Styles.CARET_DOWN : Styles.CARET_RIGHT, Styles.SUBTEXT));
            detailBody.revalidate();
            detailBody.repaint();
        });

        detailBody.add(Box.createVerticalStrut(4));
        detailBody.add(headerRow);
        detailBody.add(content);
    }

    /** Averages as an inventory-style grid; the count keeps its decimal, since that is the point. */
    private JPanel iconGrid(List<SessionHistory.ItemAverage> items) {
        JPanel grid = Styles.iconGrid();
        for (SessionHistory.ItemAverage a : items) {
            String qty = StackText.average(a.avgQtyPerTrip);
            String tip = Styles.itemCellTooltip(a.label, qty, a.avgQtyPerTrip, a.avgGpPerTrip,
                    a.isPotion, a.dosesPerPotion);
            if (a.iconItemId == null) {
                grid.add(Styles.textChip(a.label + "  " + qty, tip));
            } else {
                JLabel cell = Styles.iconCell(tip);
                itemIcons.apply(cell, a.iconItemId, qty);
                grid.add(cell);
            }
        }
        return grid;
    }

    private static JPanel grid() {
        JPanel g = new JPanel(new GridLayout(0, 2, 0, 3));
        g.setBackground(Styles.CARD);
        g.setAlignmentX(Component.LEFT_ALIGNMENT);
        return g;
    }

    private static JLabel rightValue(String text, Color color) {
        JLabel l = Styles.valueLabel(color);
        l.setText(text);
        return l;
    }

    private static JLabel boldLabel(String text, Color color, int align) {
        JLabel l = new JLabel(text);
        l.setFont(FontManager.getRunescapeBoldFont());
        l.setForeground(color);
        l.setHorizontalAlignment(align);
        return l;
    }

    private static JLabel signedValue(long value) {
        JLabel l = Styles.valueLabel(value < 0 ? Styles.NEG : Styles.GP);
        l.setText(GpFormat.format(value));
        return l;
    }
}

package com.sessiontracker.adapter.runelite;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;

/**
 * Reads the storage containers the client exposes as real item containers and folds their
 * contents into carried. Moving an item into one of these is then a net-zero change (inventory
 * down, container up), and using an item out of one is a genuine decrease.
 *
 * <p>These containers are only sent to the client once the game has a reason to (opening,
 * depositing into, or checking them), so until then they read as empty. The plugin handles the
 * first sync of each container by rebaselining that tick rather than treating the contents that
 * appear as gathered.
 */
public final class StoredContainerReader {

    private static final int[] CONTAINER_IDS = {
        InventoryID.LOOTING_BAG,
        InventoryID.SEED_BOX,
        InventoryID.FORESTRY_KIT,
        InventoryID.HUNTSMANS_KIT,
        InventoryID.TACKLE_BOX,
    };

    private final Client client;

    public StoredContainerReader(Client client) {
        this.client = client;
    }

    /** Combined contents of every readable storage container as itemId -&gt; quantity. */
    public Map<Integer, Integer> contents() {
        Map<Integer, Integer> out = new HashMap<>();
        for (int id : CONTAINER_IDS) {
            ItemContainer container = client.getItemContainer(id);
            if (container == null) {
                continue;
            }
            for (Item item : container.getItems()) {
                if (item.getId() > 0 && item.getQuantity() > 0) {
                    out.merge(item.getId(), item.getQuantity(), Integer::sum);
                }
            }
        }
        return out;
    }

    /** True if {@code containerId} is one of the storage containers folded into carried. */
    public static boolean isStoredContainer(int containerId) {
        for (int id : CONTAINER_IDS) {
            if (id == containerId) {
                return true;
            }
        }
        return false;
    }
}

package com.sessiontracker.adapter.runelite;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import javax.swing.BoxLayout;
import javax.swing.Icon;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import com.sessiontracker.adapter.GpFormat;
import com.sessiontracker.adapter.PotionFormat;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/** Shared dark-theme styling helpers so the Now / Sessions / Stats tabs look consistent. */
final class Styles {

    private Styles() {
    }

    /** A game item sprite is 36x32; the cell adds a little breathing room around it. */
    static final int ICON_CELL_W = 38;
    static final int ICON_CELL_H = 34;

    static final Color PANEL = ColorScheme.DARK_GRAY_COLOR;
    static final Color CARD = new Color(0x36, 0x36, 0x36);
    static final Color TILE = new Color(0x2b, 0x2b, 0x2b);
    static final Color ORANGE = ColorScheme.BRAND_ORANGE;
    static final Color TEXT = Color.WHITE;
    static final Color SUBTEXT = new Color(0x9a, 0x9a, 0x9a);
    static final Color GP = new Color(0x5f, 0xd3, 0x5f);
    static final Color XP = new Color(0x7f, 0xbf, 0xff);
    static final Color MISSED = new Color(0xe0, 0xa4, 0x4c);
    static final Color NEG = new Color(0xe0, 0x6c, 0x6c);

    /** A small uppercase section heading. */
    static JLabel sectionHeader(String text) {
        JLabel l = new JLabel(text.toUpperCase());
        l.setFont(FontManager.getRunescapeSmallFont());
        l.setForeground(SUBTEXT);
        l.setBorder(new EmptyBorder(9, 1, 3, 0));
        l.setAlignmentX(Component.LEFT_ALIGNMENT);
        return l;
    }

    /** A full-width card; caps its height to preferred so a vertical BoxLayout won't stretch it. */
    static JPanel card() {
        JPanel p = new JPanel() {
            @Override
            public Dimension getMaximumSize() {
                return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
            }
        };
        p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
        p.setBackground(CARD);
        p.setBorder(new EmptyBorder(8, 9, 8, 9));
        p.setAlignmentX(Component.LEFT_ALIGNMENT);
        return p;
    }

    static JButton button(String text, Color bg, Color fg) {
        JButton b = new JButton(text);
        b.setFont(FontManager.getRunescapeSmallFont());
        b.setBackground(bg);
        b.setForeground(fg);
        b.setFocusPainted(false);
        b.setBorder(new EmptyBorder(7, 8, 7, 8));
        return b;
    }

    /** A stat tile: a bold colored value over a small caption. The caller keeps {@code value} to update it. */
    static JPanel tile(JLabel value, String caption, Color valueColor) {
        JPanel t = new JPanel();
        t.setLayout(new BoxLayout(t, BoxLayout.Y_AXIS));
        t.setBackground(TILE);
        t.setBorder(new EmptyBorder(5, 7, 5, 7));
        value.setFont(FontManager.getRunescapeBoldFont());
        value.setForeground(valueColor);
        value.setAlignmentX(Component.LEFT_ALIGNMENT);
        JLabel cap = new JLabel(caption.toUpperCase());
        cap.setFont(FontManager.getRunescapeSmallFont());
        cap.setForeground(SUBTEXT);
        cap.setAlignmentX(Component.LEFT_ALIGNMENT);
        t.add(value);
        t.add(cap);
        return t;
    }

    static JLabel keyLabel(String text) {
        JLabel l = new JLabel(text);
        l.setFont(FontManager.getRunescapeSmallFont());
        l.setForeground(SUBTEXT);
        return l;
    }

    /** A skill row label: the skill name, with its icon if one was supplied. */
    static JLabel skillLabel(String skill, Icon icon) {
        JLabel l = new JLabel(skill);
        l.setFont(FontManager.getRunescapeSmallFont());
        l.setForeground(SUBTEXT);
        if (icon != null) {
            l.setIcon(icon);
            l.setIconTextGap(5);
        }
        return l;
    }

    static JLabel valueLabel(Color color) {
        JLabel l = new JLabel("-");
        l.setFont(FontManager.getRunescapeSmallFont());
        l.setForeground(color);
        l.setHorizontalAlignment(SwingConstants.RIGHT);
        return l;
    }

    /** Pins a component's max height to its preferred height (full width still allowed). */
    static void capHeight(JComponent c) {
        c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
    }

    /** Appends a bold key + bold right-aligned value (the "Total" footer row) to a 2-column grid. */
    static void addBoldRow(JPanel grid, String key, String value, Color valueColor) {
        JLabel k = new JLabel(key);
        k.setFont(FontManager.getRunescapeBoldFont());
        k.setForeground(TEXT);
        JLabel v = new JLabel(value);
        v.setFont(FontManager.getRunescapeBoldFont());
        v.setForeground(valueColor);
        v.setHorizontalAlignment(SwingConstants.RIGHT);
        grid.add(k);
        grid.add(v);
    }

    static final int CARET_RIGHT = 0;
    static final int CARET_DOWN = 1;
    static final int CARET_LEFT = 2;

    /** A small drawn triangle caret (the pixel font has no arrow/chevron glyphs). */
    static ImageIcon caret(int direction, Color color) {
        int s = 8;
        BufferedImage img = new BufferedImage(s, s, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(color);
        if (direction == CARET_DOWN) {
            g.fillPolygon(new int[]{0, s, s / 2}, new int[]{1, 1, s - 1}, 3);
        } else if (direction == CARET_LEFT) {
            g.fillPolygon(new int[]{s - 1, s - 1, 1}, new int[]{0, s, s / 2}, 3);
        } else {
            g.fillPolygon(new int[]{1, 1, s - 1}, new int[]{0, s, s / 2}, 3);
        }
        g.dispose();
        return new ImageIcon(img);
    }

    /** A borderless, transparent text button for inline "Edit"/"Back"-style affordances. */
    static JButton linkButton(String text, Color fg) {
        JButton b = new JButton(text);
        b.setFont(FontManager.getRunescapeSmallFont());
        b.setForeground(fg);
        b.setBorderPainted(false);
        b.setContentAreaFilled(false);
        b.setFocusPainted(false);
        b.setMargin(new Insets(0, 0, 0, 0));
        b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        return b;
    }

    /** A small pill-style button for reusing an existing category. */
    static JButton chip(String text) {
        JButton b = new JButton(text);
        b.setFont(FontManager.getRunescapeSmallFont());
        b.setBackground(TILE);
        b.setForeground(SUBTEXT);
        b.setFocusPainted(false);
        b.setBorder(new EmptyBorder(2, 7, 2, 7));
        b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        return b;
    }

    /**
     * Makes a card-like row behave as one big button: a press anywhere on the row — its
     * background, padding, or any label — fires {@code onClick}. {@link JButton} children
     * (and their subtrees) are skipped, so e.g. an inline "Edit" button keeps its own action.
     *
     * <p>Uses {@code mousePressed} (not {@code mouseClicked}) so a press/release on different
     * child labels still registers, and attaches the listener exactly once per component so a
     * press is never counted twice.
     */
    static void clickable(JPanel row, Runnable onClick) {
        row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        MouseAdapter ma = new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                onClick.run();
            }
        };
        attach(row, ma);
    }

    private static void attach(Component c, MouseAdapter ma) {
        if (c instanceof JButton) {
            return;
        }
        c.addMouseListener(ma);
        if (c instanceof Container) {
            for (Component child : ((Container) c).getComponents()) {
                attach(child, ma);
            }
        }
    }

    /** Full-label tooltip; for potions adds a dose→potion breakdown line. {@code doses} may be fractional. */
    /** The inventory-style grid item icons flow into, wrapping inside the narrow panel. */
    static JPanel iconGrid() {
        JPanel g = new JPanel(new WrapLayout(java.awt.FlowLayout.LEFT, 2, 2)) {
            @Override
            public Dimension getMaximumSize() {
                return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
            }
        };
        g.setBackground(CARD);
        g.setAlignmentX(Component.LEFT_ALIGNMENT);
        return g;
    }

    /**
     * An empty cell sized to a game item sprite. It keeps its slot in the grid while the icon
     * loads asynchronously, so the layout doesn't jump as images arrive.
     */
    static JLabel iconCell(String tooltip) {
        JLabel l = new JLabel();
        l.setPreferredSize(new Dimension(ICON_CELL_W, ICON_CELL_H));
        l.setToolTipText(tooltip);
        return l;
    }

    /** Fallback for an item with no resolvable sprite: its name and count, in the same flow. */
    static JLabel textChip(String text, String tooltip) {
        JLabel l = new JLabel(text);
        l.setFont(FontManager.getRunescapeSmallFont());
        l.setForeground(SUBTEXT);
        l.setBorder(new EmptyBorder(2, 4, 2, 4));
        l.setToolTipText(tooltip);
        return l;
    }

    /** An icon cell's tooltip: the name, the quantity (with potions for doses), and the value. */
    static String itemCellTooltip(String label, String quantityText, double quantity, long gpValue,
                                  boolean isPotion, int dosesPerPotion) {
        StringBuilder sb = new StringBuilder("<html>").append(escapeHtml(label));
        sb.append("<br>×").append(quantityText);
        if (isPotion) {
            sb.append(" ≈ ").append(PotionFormat.potions(quantity, dosesPerPotion));
        }
        sb.append("<br>").append(GpFormat.format(gpValue));
        return sb.append("</html>").toString();
    }

    static String itemTooltip(String label, double doses, boolean isPotion, int dosesPerPotion) {
        if (!isPotion) {
            return label;
        }
        String doseStr = doses == Math.rint(doses)
                ? Long.toString((long) doses)
                : String.format(java.util.Locale.US, "%.1f", doses);
        return "<html>" + escapeHtml(label) + "<br>" + doseStr + " doses ≈ "
                + PotionFormat.potions(doses, dosesPerPotion) + "</html>";
    }

    private static String escapeHtml(String s) {
        return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }
}

