package com.sessiontracker.adapter.runelite;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Insets;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;

/**
 * A {@link FlowLayout} that wraps its rows and reports a correct multi-row preferred size,
 * so chips flow onto new lines inside the narrow plugin panel. (Standard FlowLayout reports
 * a single-row preferred height and gets clipped.)
 */
final class WrapLayout extends FlowLayout {

    WrapLayout(int align, int hgap, int vgap) {
        super(align, hgap, vgap);
    }

    @Override
    public Dimension preferredLayoutSize(Container target) {
        return layoutSize(target, true);
    }

    @Override
    public Dimension minimumLayoutSize(Container target) {
        Dimension minimum = layoutSize(target, false);
        minimum.width -= (getHgap() + 1);
        return minimum;
    }

    private Dimension layoutSize(Container target, boolean preferred) {
        synchronized (target.getTreeLock()) {
            int targetWidth = target.getSize().width;
            if (targetWidth == 0) {
                // The enclosing BoxLayout asks how tall we want to be before we have been given
                // a width. Answering as if the row were unbounded reports a single row, and the
                // rows that do wrap are then clipped, so measure against the space we will get.
                targetWidth = availableWidth(target.getParent());
            }
            if (targetWidth == 0) {
                targetWidth = Integer.MAX_VALUE;
            }
            int hgap = getHgap();
            int vgap = getVgap();
            Insets insets = target.getInsets();
            int horizontalInsetsAndGap = insets.left + insets.right + (hgap * 2);
            int maxWidth = targetWidth - horizontalInsetsAndGap;

            Dimension dim = new Dimension(0, 0);
            int rowWidth = 0;
            int rowHeight = 0;
            for (int i = 0; i < target.getComponentCount(); i++) {
                Component m = target.getComponent(i);
                if (!m.isVisible()) {
                    continue;
                }
                Dimension d = preferred ? m.getPreferredSize() : m.getMinimumSize();
                if (rowWidth + d.width > maxWidth) {
                    addRow(dim, rowWidth, rowHeight, vgap);
                    rowWidth = 0;
                    rowHeight = 0;
                }
                if (rowWidth != 0) {
                    rowWidth += hgap;
                }
                rowWidth += d.width;
                rowHeight = Math.max(rowHeight, d.height);
            }
            addRow(dim, rowWidth, rowHeight, vgap);

            dim.width += horizontalInsetsAndGap;
            dim.height += insets.top + insets.bottom + vgap * 2;

            Container scrollPane = SwingUtilities.getAncestorOfClass(JScrollPane.class, target);
            if (scrollPane != null && target.isValid()) {
                dim.width -= (hgap + 1);
            }
            return dim;
        }
    }

    /** The content width of the nearest ancestor that has been sized, or 0 if none has. */
    private static int availableWidth(Container parent) {
        for (Container c = parent; c != null; c = c.getParent()) {
            int width = c.getSize().width;
            if (width > 0) {
                Insets insets = c.getInsets();
                return Math.max(0, width - insets.left - insets.right);
            }
        }
        return 0;
    }

    private void addRow(Dimension dim, int rowWidth, int rowHeight, int vgap) {
        dim.width = Math.max(dim.width, rowWidth);
        if (dim.height > 0) {
            dim.height += vgap;
        }
        dim.height += rowHeight;
    }
}

package com.sessiontracker.core;

import com.sessiontracker.core.item.ItemValuer;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

/** Groups sessions by category and computes {@link CategoryStats} for each. */
public final class CategoryAggregator {

    private CategoryAggregator() {
    }

    public static Map<String, CategoryStats> aggregate(List<Session> sessions, ItemValuer valuer) {
        return aggregate(sessions, t -> valuer);
    }

    public static Map<String, CategoryStats> aggregate(
            List<Session> sessions, Function<Trip, ItemValuer> valuerFn) {
        Map<String, List<Session>> byCategory = new LinkedHashMap<>();
        for (Session s : sessions) {
            byCategory.computeIfAbsent(s.category(), k -> new ArrayList<>()).add(s);
        }
        Map<String, CategoryStats> result = new HashMap<>();
        for (Map.Entry<String, List<Session>> e : byCategory.entrySet()) {
            result.put(e.getKey(), CategoryStats.from(e.getKey(), e.getValue(), valuerFn));
        }
        return result;
    }
}

package com.sessiontracker.core;

import com.sessiontracker.core.item.ItemKey;
import com.sessiontracker.core.item.ItemValuer;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

/** Aggregated averages across all sessions sharing a category. */
public final class CategoryStats {

    private static final long MILLIS_PER_HOUR = 3_600_000L;

    private final String category;
    private final int sessionCount;
    private final int tripCount;
    private final long gpPerHour;
    private final long xpPerHour;
    private final long avgTripDurationMillis;
    private final long avgSessionDurationMillis;
    private final long avgNetProfitPerTrip;
    private final long avgMissedPerTrip;
    private final double avgKillsPerTrip;
    private final Map<ItemKey, Double> avgSuppliesPerTrip;

    private CategoryStats(String category, int sessionCount, int tripCount, long gpPerHour,
                          long xpPerHour, long avgTripDurationMillis, long avgSessionDurationMillis,
                          long avgNetProfitPerTrip, long avgMissedPerTrip, double avgKillsPerTrip,
                          Map<ItemKey, Double> avgSuppliesPerTrip) {
        this.category = category;
        this.sessionCount = sessionCount;
        this.tripCount = tripCount;
        this.gpPerHour = gpPerHour;
        this.xpPerHour = xpPerHour;
        this.avgTripDurationMillis = avgTripDurationMillis;
        this.avgSessionDurationMillis = avgSessionDurationMillis;
        this.avgNetProfitPerTrip = avgNetProfitPerTrip;
        this.avgMissedPerTrip = avgMissedPerTrip;
        this.avgKillsPerTrip = avgKillsPerTrip;
        this.avgSuppliesPerTrip = avgSuppliesPerTrip;
    }

    public static CategoryStats from(String category, List<Session> sessions, ItemValuer valuer) {
        return from(category, sessions, t -> valuer);
    }

    public static CategoryStats from(String category, List<Session> sessions,
                                     Function<Trip, ItemValuer> valuerFn) {
        int tripCount = 0;
        long totalWallClock = 0;
        long totalNet = 0;
        long totalXp = 0;
        long totalTripDuration = 0;
        long totalMissed = 0;
        int totalKills = 0;
        Map<ItemKey, Long> totalSupplies = new HashMap<>();

        for (Session s : sessions) {
            totalWallClock += s.wallClockMillis();
            totalXp += s.totalXp();
            for (Trip t : s.trips()) {
                ItemValuer valuer = valuerFn.apply(t);
                tripCount++;
                totalNet += t.netProfit(valuer);
                totalTripDuration += t.durationMillis();
                totalMissed += t.missedValue(valuer);
                totalKills += t.totalKills();
                for (Map.Entry<ItemKey, Integer> e : t.suppliesUsed().entrySet()) {
                    totalSupplies.merge(e.getKey(), e.getValue().longValue(), Long::sum);
                }
            }
        }

        long gpPerHour = totalWallClock <= 0 ? 0 : totalNet * MILLIS_PER_HOUR / totalWallClock;
        long xpPerHour = totalWallClock <= 0 ? 0 : totalXp * MILLIS_PER_HOUR / totalWallClock;
        long avgDuration = tripCount == 0 ? 0 : totalTripDuration / tripCount;
        long avgSessionDuration = sessions.isEmpty() ? 0 : totalWallClock / sessions.size();
        long avgNet = tripCount == 0 ? 0 : totalNet / tripCount;
        long avgMissed = tripCount == 0 ? 0 : totalMissed / tripCount;
        double avgKills = tripCount == 0 ? 0 : (double) totalKills / tripCount;

        Map<ItemKey, Double> avgSupplies = new HashMap<>();
        if (tripCount > 0) {
            for (Map.Entry<ItemKey, Long> e : totalSupplies.entrySet()) {
                avgSupplies.put(e.getKey(), (double) e.getValue() / tripCount);
            }
        }

        return new CategoryStats(category, sessions.size(), tripCount, gpPerHour, xpPerHour,
                avgDuration, avgSessionDuration, avgNet, avgMissed, avgKills, avgSupplies);
    }

    public String category() {
        return category;
    }

    public int sessionCount() {
        return sessionCount;
    }

    public int tripCount() {
        return tripCount;
    }

    public long gpPerHour() {
        return gpPerHour;
    }

    public long xpPerHour() {
        return xpPerHour;
    }

    public long avgTripDurationMillis() {
        return avgTripDurationMillis;
    }

    public long avgSessionDurationMillis() {
        return avgSessionDurationMillis;
    }

    public long avgNetProfitPerTrip() {
        return avgNetProfitPerTrip;
    }

    public long avgMissedPerTrip() {
        return avgMissedPerTrip;
    }

    public double avgKillsPerTrip() {
        return avgKillsPerTrip;
    }

    public Map<ItemKey, Double> avgSuppliesPerTrip() {
        return Collections.unmodifiableMap(avgSuppliesPerTrip);
    }
}

package com.sessiontracker.core;

import com.sessiontracker.core.item.ItemValuer;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.Function;

/** An ordered collection of trips for one activity, plus its editable labels. */
public final class Session {

    private static final long MILLIS_PER_HOUR = 3_600_000L;

    private final String id;
    private final String accountHash;
    private String category;
    private String name;
    private final List<Trip> trips;
    // Time the session spent resumed-after-ending, excluded from its wall clock so a session
    // picked up again the next day is not rated as if it ran all night.
    private final long pausedMillis;

    public Session(String id, String accountHash, String category, String name, List<Trip> trips) {
        this(id, accountHash, category, name, trips, 0);
    }

    public Session(String id, String accountHash, String category, String name, List<Trip> trips,
                   long pausedMillis) {
        this.id = id;
        this.accountHash = accountHash;
        this.category = category;
        this.name = name;
        this.trips = new ArrayList<>(trips);
        this.pausedMillis = pausedMillis;
    }

    public long pausedMillis() {
        return pausedMillis;
    }

    public String id() {
        return id;
    }

    public String accountHash() {
        return accountHash;
    }

    public String category() {
        return category;
    }

    public void setCategory(String category) {
        this.category = category;
    }

    public String name() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public List<Trip> trips() {
        return Collections.unmodifiableList(trips);
    }

    public long wallClockMillis() {
        if (trips.isEmpty()) {
            return 0;
        }
        long first = Long.MAX_VALUE;
        long last = Long.MIN_VALUE;
        for (Trip t : trips) {
            first = Math.min(first, t.startMillis());
            last = Math.max(last, t.endMillis());
        }
        return Math.max(0, last - first - pausedMillis);
    }

    public long totalNetProfit(Function<Trip, ItemValuer> valuerFn) {
        long sum = 0;
        for (Trip t : trips) {
            sum += t.netProfit(valuerFn.apply(t));
        }
        return sum;
    }

    public long totalNetProfit(ItemValuer valuer) {
        return totalNetProfit(t -> valuer);
    }

    public long totalXp() {
        long sum = 0;
        for (Trip t : trips) {
            sum += t.totalXp();
        }
        return sum;
    }

    public long gpPerHour(Function<Trip, ItemValuer> valuerFn) {
        long ms = wallClockMillis();
        return ms <= 0 ? 0 : totalNetProfit(valuerFn) * MILLIS_PER_HOUR / ms;
    }

    public long gpPerHour(ItemValuer valuer) {
        return gpPerHour(t -> valuer);
    }

    public long xpPerHour() {
        long ms = wallClockMillis();
        return ms <= 0 ? 0 : totalXp() * MILLIS_PER_HOUR / ms;
    }
}

package com.sessiontracker.core;

import com.sessiontracker.core.item.ItemKey;
import com.sessiontracker.core.item.ItemValuer;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/** Immutable record of a single completed trip. Quantities only; gp is derived via an ItemValuer. */
public final class Trip {

    private final String id;
    private final long startMillis;
    private final long endMillis;
    private final boolean died;
    private final Map<String, Integer> kills;
    private final Map<ItemKey, Integer> dropped;
    private final Map<ItemKey, Integer> pickedUp;
    private final Map<ItemKey, Integer> missed;
    private final Map<ItemKey, Integer> suppliesUsed;
    private final Map<ItemKey, Integer> gathered;
    // Items acquired this trip (looted or gathered) that were later consumed. They cost
    // nothing, so they are not supplies; they net against this trip's income instead.
    private final Map<ItemKey, Integer> consumedLoot;
    private final Map<String, Long> xpGained;

    public Trip(String id, long startMillis, long endMillis, boolean died,
                Map<String, Integer> kills, Map<ItemKey, Integer> dropped,
                Map<ItemKey, Integer> pickedUp, Map<ItemKey, Integer> missed,
                Map<ItemKey, Integer> suppliesUsed, Map<String, Long> xpGained) {
        this(id, startMillis, endMillis, died, kills, dropped, pickedUp, missed,
                suppliesUsed, new HashMap<>(), xpGained);
    }

    public Trip(String id, long startMillis, long endMillis, boolean died,
                Map<String, Integer> kills, Map<ItemKey, Integer> dropped,
                Map<ItemKey, Integer> pickedUp, Map<ItemKey, Integer> missed,
                Map<ItemKey, Integer> suppliesUsed, Map<ItemKey, Integer> gathered,
                Map<String, Long> xpGained) {
        this(id, startMillis, endMillis, died, kills, dropped, pickedUp, missed,
                suppliesUsed, gathered, new HashMap<>(), xpGained);
    }

    public Trip(String id, long startMillis, long endMillis, boolean died,
                Map<String, Integer> kills, Map<ItemKey, Integer> dropped,
                Map<ItemKey, Integer> pickedUp, Map<ItemKey, Integer> missed,
                Map<ItemKey, Integer> suppliesUsed, Map<ItemKey, Integer> gathered,
                Map<ItemKey, Integer> consumedLoot, Map<String, Long> xpGained) {
        this.id = id;
        this.startMillis = startMillis;
        this.endMillis = endMillis;
        this.died = died;
        this.kills = new HashMap<>(kills);
        this.dropped = new HashMap<>(dropped);
        this.pickedUp = new HashMap<>(pickedUp);
        this.missed = new HashMap<>(missed);
        this.suppliesUsed = new HashMap<>(suppliesUsed);
        this.gathered = new HashMap<>(gathered);
        this.consumedLoot = new HashMap<>(consumedLoot);
        this.xpGained = new HashMap<>(xpGained);
    }

    public String id() {
        return id;
    }

    public long startMillis() {
        return startMillis;
    }

    public long endMillis() {
        return endMillis;
    }

    public long durationMillis() {
        return endMillis - startMillis;
    }

    public boolean died() {
        return died;
    }

    public Map<String, Integer> kills() {
        return Collections.unmodifiableMap(kills);
    }

    public Map<ItemKey, Integer> dropped() {
        return Collections.unmodifiableMap(dropped);
    }

    public Map<ItemKey, Integer> pickedUp() {
        return Collections.unmodifiableMap(pickedUp);
    }

    public Map<ItemKey, Integer> missed() {
        return Collections.unmodifiableMap(missed);
    }

    public Map<ItemKey, Integer> suppliesUsed() {
        return Collections.unmodifiableMap(suppliesUsed);
    }

    public Map<ItemKey, Integer> gathered() {
        return Collections.unmodifiableMap(gathered);
    }

    public Map<ItemKey, Integer> consumedLoot() {
        return Collections.unmodifiableMap(consumedLoot);
    }

    /**
     * Picked-up loot still in hand at trip end: gross pickedUp minus the portion later
     * consumed. Consumed acquisitions are attributed to loot before gathered, matching
     * {@link #gatheredKept()}. The gross {@link #pickedUp()} is left intact for the
     * left-on-ground calculation; this is the "what you kept" view for display.
     */
    public Map<ItemKey, Integer> pickedUpKept() {
        Map<ItemKey, Integer> out = new HashMap<>();
        for (Map.Entry<ItemKey, Integer> e : pickedUp.entrySet()) {
            int fromPicked = Math.min(consumedLoot.getOrDefault(e.getKey(), 0), e.getValue());
            int kept = e.getValue() - fromPicked;
            if (kept > 0) {
                out.put(e.getKey(), kept);
            }
        }
        return out;
    }

    /** Gathered resources still in hand at trip end: gross gathered minus the portion consumed. */
    public Map<ItemKey, Integer> gatheredKept() {
        Map<ItemKey, Integer> out = new HashMap<>();
        for (Map.Entry<ItemKey, Integer> e : gathered.entrySet()) {
            int consumed = consumedLoot.getOrDefault(e.getKey(), 0);
            int fromPicked = Math.min(consumed, pickedUp.getOrDefault(e.getKey(), 0));
            int fromGathered = Math.min(e.getValue(), consumed - fromPicked);
            int kept = e.getValue() - fromGathered;
            if (kept > 0) {
                out.put(e.getKey(), kept);
            }
        }
        return out;
    }

    public Map<String, Long> xpGained() {
        return Collections.unmodifiableMap(xpGained);
    }

    public int totalKills() {
        int sum = 0;
        for (int c : kills.values()) {
            sum += c;
        }
        return sum;
    }

    public long totalXp() {
        long sum = 0;
        for (long v : xpGained.values()) {
            sum += v;
        }
        return sum;
    }

    public long pickedUpValue(ItemValuer valuer) {
        return value(pickedUp, valuer);
    }

    public long gatheredValue(ItemValuer valuer) {
        return value(gathered, valuer);
    }

    public long pickedUpKeptValue(ItemValuer valuer) {
        return value(pickedUpKept(), valuer);
    }

    public long gatheredKeptValue(ItemValuer valuer) {
        return value(gatheredKept(), valuer);
    }

    public long consumedLootValue(ItemValuer valuer) {
        return value(consumedLoot, valuer);
    }

    public long suppliesValue(ItemValuer valuer) {
        return value(suppliesUsed, valuer);
    }

    public long missedValue(ItemValuer valuer) {
        return value(missed, valuer);
    }

    public long netProfit(ItemValuer valuer) {
        return pickedUpValue(valuer) + gatheredValue(valuer)
                - consumedLootValue(valuer) - suppliesValue(valuer);
    }

    private static long value(Map<ItemKey, Integer> items, ItemValuer valuer) {
        long sum = 0;
        for (Map.Entry<ItemKey, Integer> e : items.entrySet()) {
            sum += valuer.value(e.getKey(), e.getValue());
        }
        return sum;
    }
}

package com.sessiontracker.core;

import com.sessiontracker.core.item.ItemKey;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * Event-ordered tracking ledger for a single in-progress trip.
 *
 * <p>Contract: {@link #updateCarried(Map)} must be called once per settled game
 * tick with the combined, dose-normalized inventory+equipment quantities. A
 * positive per-tick delta is reconciled against the still-on-the-ground pool
 * (kill loot picked up, else an untracked generic gain); a negative delta is
 * recorded as supplies used.
 */
public final class TripLedger {

    private final Map<String, Integer> kills = new HashMap<>();
    private final Map<ItemKey, Integer> dropped = new HashMap<>();
    private final Map<ItemKey, Integer> groundPool = new HashMap<>();
    private final Map<ItemKey, Integer> pickedUp = new HashMap<>();
    private final Map<ItemKey, Integer> suppliesUsed = new HashMap<>();
    // Brought items that were dropped and charged as supplies, but are still on the ground
    // and recoverable: picking one back up reverses that supply charge.
    private final Map<ItemKey, Integer> droppedBrought = new HashMap<>();
    private final Map<ItemKey, Integer> gathered = new HashMap<>();
    // Acquired-this-trip items (looted or gathered) that were later consumed: free, so not supplies.
    private final Map<ItemKey, Integer> consumedLoot = new HashMap<>();
    private final Map<String, Long> xp = new HashMap<>();

    // The first item gathered this trip, in encounter order (for auto-naming the session).
    private ItemKey firstGathered = null;

    private Map<ItemKey, Integer> carried = null;

    /**
     * A ledger that continues a completed trip: everything the trip recorded is restored, and
     * its loot still on the ground goes back into the ground pool so a later pickup reconciles
     * as loot. The carried baseline is left unset; call {@link #rebaseline(Map)} with the
     * current inventory before the next tick.
     */
    public static TripLedger resuming(Trip trip) {
        TripLedger ledger = new TripLedger();
        ledger.absorb(trip);
        return ledger;
    }

    /** Add everything {@code trip} recorded to this ledger (used to merge a split trip back). */
    public void absorb(Trip trip) {
        trip.kills().forEach((npc, n) -> kills.merge(npc, n, Integer::sum));
        trip.dropped().forEach((k, n) -> dropped.merge(k, n, Integer::sum));
        trip.pickedUp().forEach((k, n) -> pickedUp.merge(k, n, Integer::sum));
        trip.missed().forEach((k, n) -> groundPool.merge(k, n, Integer::sum));
        trip.suppliesUsed().forEach((k, n) -> suppliesUsed.merge(k, n, Integer::sum));
        trip.gathered().forEach((k, n) -> gathered.merge(k, n, Integer::sum));
        trip.consumedLoot().forEach((k, n) -> consumedLoot.merge(k, n, Integer::sum));
        trip.xpGained().forEach((skill, n) -> xp.merge(skill, n, Long::sum));
    }

    public void recordKill(String npcName, Map<ItemKey, Integer> drops) {
        kills.merge(npcName, 1, Integer::sum);
        for (Map.Entry<ItemKey, Integer> e : drops.entrySet()) {
            int qty = e.getValue();
            if (qty <= 0) {
                continue;
            }
            dropped.merge(e.getKey(), qty, Integer::sum);
            groundPool.merge(e.getKey(), qty, Integer::sum);
        }
    }

    public void updateCarried(Map<ItemKey, Integer> settledCarried) {
        updateCarried(settledCarried, Collections.emptySet());
    }

    /**
     * Reset the delta baseline to {@code settledCarried} without recording anything. Used while
     * the bank is open: deposits and withdrawals change the inventory but are neither supplies
     * consumed nor resources gained, so they must be absorbed rather than reconciled.
     */
    public void rebaseline(Map<ItemKey, Integer> settledCarried) {
        carried = new HashMap<>(settledCarried);
    }

    public void updateCarried(Map<ItemKey, Integer> settledCarried, Set<ItemKey> droppedThisTick) {
        if (carried == null) {
            carried = new HashMap<>(settledCarried);
            return;
        }
        Set<ItemKey> keys = new HashSet<>();
        keys.addAll(carried.keySet());
        keys.addAll(settledCarried.keySet());
        for (ItemKey key : keys) {
            int delta = settledCarried.getOrDefault(key, 0) - carried.getOrDefault(key, 0);
            if (delta > 0) {
                reconcilePickup(key, delta);
            } else if (delta < 0) {
                int lost = -delta;
                if (droppedThisTick.contains(key)) {
                    reverseDrop(key, lost);
                } else {
                    consume(key, lost);
                }
            }
        }
        carried = new HashMap<>(settledCarried);
    }

    private void reconcilePickup(ItemKey key, int gained) {
        int remaining = gained;
        // First, reverse any brought item we dropped earlier this trip: picking it back up
        // undoes the supply we charged when it was dropped.
        int broughtBack = Math.min(remaining, droppedBrought.getOrDefault(key, 0));
        if (broughtBack > 0) {
            decrement(suppliesUsed, key, broughtBack);
            decrement(droppedBrought, key, broughtBack);
            remaining -= broughtBack;
        }
        // Then, reconcile against kill loot still on the ground.
        int onGround = groundPool.getOrDefault(key, 0);
        int fromGround = Math.min(remaining, onGround);
        if (fromGround > 0) {
            pickedUp.merge(key, fromGround, Integer::sum);
            decrement(groundPool, key, fromGround);
            remaining -= fromGround;
        }
        // Any further gain is a non-loot inventory gain (e.g. a gathered resource).
        if (remaining > 0) {
            gathered.merge(key, remaining, Integer::sum);
            if (firstGathered == null) {
                firstGathered = key;
            }
        }
    }

    private void consume(ItemKey key, int lost) {
        // An item consumed (eaten, buried, burnt, cast...) is a supply only to the extent it
        // wasn't acquired this trip. Cancel it against this trip's still-unconsumed loot and
        // gathered resources first; only the remainder was brought, so only that is a supply.
        int acquired = pickedUp.getOrDefault(key, 0) + gathered.getOrDefault(key, 0);
        int available = Math.max(0, acquired - consumedLoot.getOrDefault(key, 0));
        int free = Math.min(lost, available);
        if (free > 0) {
            consumedLoot.merge(key, free, Integer::sum);
        }
        int brought = lost - free;
        if (brought > 0) {
            suppliesUsed.merge(key, brought, Integer::sum);
        }
    }

    private void reverseDrop(ItemKey key, int lost) {
        int pickedUpQty = pickedUp.getOrDefault(key, 0);
        int reversed = Math.min(lost, pickedUpQty);
        if (reversed > 0) {
            decrement(pickedUp, key, reversed);
            // Back on the ground so a later re-pickup reconciles as loot again.
            groundPool.merge(key, reversed, Integer::sum);
        }
        int brought = lost - reversed;
        if (brought > 0) {
            suppliesUsed.merge(key, brought, Integer::sum);
            // Remember it's recoverable: picking it back up reverses this supply charge.
            droppedBrought.merge(key, brought, Integer::sum);
        }
    }

    private static void decrement(Map<ItemKey, Integer> map, ItemKey key, int amount) {
        int remaining = map.getOrDefault(key, 0) - amount;
        if (remaining <= 0) {
            map.remove(key);
        } else {
            map.put(key, remaining);
        }
    }

    /** The first item gathered this trip, or {@code null} if nothing has been gathered yet. */
    public ItemKey firstGathered() {
        return firstGathered;
    }

    public void recordXp(String skill, long delta) {
        if (delta > 0) {
            xp.merge(skill, delta, Long::sum);
        }
    }

    /**
     * Builds the immutable {@link Trip}. Non-destructive: the ledger may be queried again.
     * Any loot dropped before the first {@link #updateCarried(Map)} baseline cannot be
     * reconciled to a pickup, so it is reported entirely as missed.
     */
    public Trip build(String id, long startMillis, long endMillis, boolean died) {
        Map<ItemKey, Integer> missed = new HashMap<>();
        for (Map.Entry<ItemKey, Integer> e : dropped.entrySet()) {
            int remaining = e.getValue() - pickedUp.getOrDefault(e.getKey(), 0);
            if (remaining > 0) {
                missed.put(e.getKey(), remaining);
            }
        }
        return new Trip(id, startMillis, endMillis, died,
                kills, dropped, pickedUp, missed, suppliesUsed, gathered, consumedLoot, xp);
    }
}

package com.sessiontracker.core.item;

import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.function.IntFunction;

/**
 * Converts a raw combined inventory+equipment snapshot (itemId -> quantity)
 * into normalized {@link ItemKey} quantities, where potion ids collapse into a
 * single per-family key valued in total doses.
 */
public final class CarriedNormalizer {

    private CarriedNormalizer() {
    }

    public static Map<ItemKey, Integer> normalize(Map<Integer, Integer> rawCombined,
                                                   IntFunction<String> nameLookup) {
        Map<ItemKey, Integer> out = new HashMap<>();
        for (Map.Entry<Integer, Integer> entry : rawCombined.entrySet()) {
            int id = entry.getKey();
            int qty = entry.getValue();
            if (qty <= 0) {
                continue;
            }
            Optional<DoseForm> form = Doses.parse(nameLookup.apply(id));
            if (form.isPresent()) {
                out.merge(ItemKey.potion(form.get().family()), form.get().dose() * qty, Integer::sum);
            } else {
                out.merge(ItemKey.item(id), qty, Integer::sum);
            }
        }
        return out;
    }
}

package com.sessiontracker.core.item;

import java.util.Objects;

/** The parsed dose/charge information from an item name, e.g. {"Prayer potion", 4}. */
public final class DoseForm {

    private final String family;
    private final int dose;

    public DoseForm(String family, int dose) {
        this.family = family;
        this.dose = dose;
    }

    public String family() {
        return family;
    }

    public int dose() {
        return dose;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof DoseForm)) {
            return false;
        }
        DoseForm other = (DoseForm) o;
        return dose == other.dose && Objects.equals(family, other.family);
    }

    @Override
    public int hashCode() {
        return Objects.hash(family, dose);
    }
}

package com.sessiontracker.core.item;

import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Parses dose/charge information from item names like "Prayer potion(4)".
 * Matches a trailing "(<digits>)" suffix, which in OSRS denotes potion doses
 * (and, accepted for v1, charged jewellery like "Games necklace(8)").
 */
public final class Doses {

    private static final Pattern DOSE = Pattern.compile("^(.*)\\((\\d+)\\)$");

    private Doses() {
    }

    public static Optional<DoseForm> parse(String name) {
        if (name == null) {
            return Optional.empty();
        }
        Matcher matcher = DOSE.matcher(name.trim());
        if (!matcher.matches()) {
            return Optional.empty();
        }
        String family = matcher.group(1).trim();
        int dose = Integer.parseInt(matcher.group(2));
        if (family.isEmpty() || dose <= 0) {
            return Optional.empty();
        }
        return Optional.of(new DoseForm(family, dose));
    }
}

package com.sessiontracker.core.item;

import java.util.Objects;

/** Identifies a tracked quantity: either a normal item (by id) or a potion family (by name). */
public final class ItemKey {

    private final int itemId;          // -1 for potion-family keys
    private final String potionFamily; // null for normal-item keys

    private ItemKey(int itemId, String potionFamily) {
        this.itemId = itemId;
        this.potionFamily = potionFamily;
    }

    public static ItemKey item(int itemId) {
        return new ItemKey(itemId, null);
    }

    public static ItemKey potion(String family) {
        return new ItemKey(-1, Objects.requireNonNull(family));
    }

    public boolean isPotion() {
        return potionFamily != null;
    }

    public int itemId() {
        if (isPotion()) {
            throw new IllegalStateException("ItemKey is a potion family, not an item");
        }
        return itemId;
    }

    public String potionFamily() {
        if (!isPotion()) {
            throw new IllegalStateException("ItemKey is an item, not a potion family");
        }
        return potionFamily;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof ItemKey)) {
            return false;
        }
        ItemKey other = (ItemKey) o;
        return itemId == other.itemId && Objects.equals(potionFamily, other.potionFamily);
    }

    @Override
    public int hashCode() {
        return Objects.hash(itemId, potionFamily);
    }

    @Override
    public String toString() {
        return isPotion() ? "potion:" + potionFamily : "item:" + itemId;
    }
}

