        SessionHistory history = new SessionHistory(store, "acct", names);
        SessionHistory.CategoryDetail d = history.categoryDetail("Vorkath");

        // Picked: coins 300qty/300gp, scale 1qty/10gp -> /2 trips; sorted gp desc (coins first)
