package com.sessiontracker.adapter;

import static org.junit.Assert.*;
import com.sessiontracker.core.Trip;
import com.sessiontracker.core.item.ItemKey;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class SessionMapperTest {

    private Trip sampleTrip() {
        Map<String, Integer> kills = new HashMap<>();
        kills.put("Demonic gorilla", 2);
        Map<ItemKey, Integer> dropped = new HashMap<>();
        dropped.put(ItemKey.item(560), 100);
        Map<ItemKey, Integer> pickedUp = new HashMap<>();
        pickedUp.put(ItemKey.item(560), 60);
        Map<ItemKey, Integer> missed = new HashMap<>();
        missed.put(ItemKey.item(560), 40);
        Map<ItemKey, Integer> supplies = new HashMap<>();
        supplies.put(ItemKey.potion("Prayer potion"), 3);
        Map<ItemKey, Integer> gathered = new HashMap<>();
        gathered.put(ItemKey.item(1511), 27);
        Map<String, Long> xp = new HashMap<>();
        xp.put("RANGED", 5000L);
        return new Trip("t1", 0, 60_000, false, kills, dropped, pickedUp, missed, supplies,
                gathered, xp);
    }

    @Test
    public void encodesTripWithItemKeyTokens() {
        Map<ItemKey, Long> prices = new HashMap<>();
        prices.put(ItemKey.item(560), 5L);
        prices.put(ItemKey.potion("Prayer potion"), 250L);

        StoredTrip stored = SessionMapper.toStored(sampleTrip(), prices);

        assertEquals("t1", stored.id);
        assertEquals(Integer.valueOf(100), stored.dropped.get("item:560"));
        assertEquals(Integer.valueOf(3), stored.suppliesUsed.get("potion:Prayer potion"));
        assertEquals(Long.valueOf(250L), stored.unitPrices.get("potion:Prayer potion"));
    }

    @Test
    public void roundTripsConsumedLootAndToleratesMissingField() {
        ItemKey shark = ItemKey.item(385);
        Map<ItemKey, Integer> consumed = new HashMap<>();
        consumed.put(shark, 3);
        Trip trip = new Trip("t1", 0, 60_000, false, new HashMap<>(), new HashMap<>(),
                new HashMap<>(), new HashMap<>(), new HashMap<>(), new HashMap<>(), consumed,
                new HashMap<>());
        StoredTrip stored = SessionMapper.toStored(trip, new HashMap<>());
        assertEquals(Integer.valueOf(3), stored.consumedLoot.get("item:385"));
        assertEquals(Integer.valueOf(3), SessionMapper.toTrip(stored).consumedLoot().get(shark));

        stored.consumedLoot = null; // session saved before this field existed
        assertTrue(SessionMapper.toTrip(stored).consumedLoot().isEmpty());
    }

    @Test
    public void roundTripsBackToCoreTrip() {
        Map<ItemKey, Long> prices = new HashMap<>();
        prices.put(ItemKey.item(560), 5L);
        StoredTrip stored = SessionMapper.toStored(sampleTrip(), prices);

        Trip restored = SessionMapper.toTrip(stored);
        assertEquals(2, restored.totalKills());
        assertEquals(Integer.valueOf(60), restored.pickedUp().get(ItemKey.item(560)));
        assertEquals(Integer.valueOf(3), restored.suppliesUsed().get(ItemKey.potion("Prayer potion")));

        Map<ItemKey, Long> restoredPrices = SessionMapper.unitPrices(stored);
        assertEquals(Long.valueOf(5L), restoredPrices.get(ItemKey.item(560)));
    }

    @Test
    public void toSessionAndValuerForValueEachTripWithCapturedPrices() {
        com.sessiontracker.core.item.ItemKey coins = com.sessiontracker.core.item.ItemKey.item(560);
        java.util.Map<com.sessiontracker.core.item.ItemKey, Integer> picked = new java.util.HashMap<>();
        picked.put(coins, 10);

        com.sessiontracker.core.Trip ta = new com.sessiontracker.core.Trip("a", 0, 3_600_000L, false,
                new java.util.HashMap<>(), new java.util.HashMap<>(), new java.util.HashMap<>(picked),
                new java.util.HashMap<>(), new java.util.HashMap<>(), new java.util.HashMap<>());
        com.sessiontracker.core.Trip tb = new com.sessiontracker.core.Trip("b", 3_600_000L, 7_200_000L, false,
                new java.util.HashMap<>(), new java.util.HashMap<>(), new java.util.HashMap<>(picked),
                new java.util.HashMap<>(), new java.util.HashMap<>(), new java.util.HashMap<>());

        java.util.Map<com.sessiontracker.core.item.ItemKey, Long> priceA = new java.util.HashMap<>();
        priceA.put(coins, 2L);
        java.util.Map<com.sessiontracker.core.item.ItemKey, Long> priceB = new java.util.HashMap<>();
        priceB.put(coins, 5L);

        StoredSession stored = new StoredSession();
        stored.id = "s";
        stored.accountHash = "acct";
        stored.category = "Vorkath";
        stored.name = "evening";
        stored.startMillis = 0;
        stored.endMillis = 7_200_000L;
        stored.trips = java.util.Arrays.asList(
                SessionMapper.toStored(ta, priceA), SessionMapper.toStored(tb, priceB));

        com.sessiontracker.core.Session session = SessionMapper.toSession(stored);
        assertEquals("Vorkath", session.category());
        assertEquals("evening", session.name());
        assertEquals(2, session.trips().size());

        java.util.function.Function<com.sessiontracker.core.Trip, com.sessiontracker.core.item.ItemValuer> fn =
                SessionMapper.valuerFor(stored);
        assertEquals(70L, session.totalNetProfit(fn));
    }

    @Test
    public void encodesAndRoundTripsGathered() {
        Map<ItemKey, Long> prices = new HashMap<>();
        prices.put(ItemKey.item(1511), 50L);
        StoredTrip stored = SessionMapper.toStored(sampleTrip(), prices);
        assertEquals(Integer.valueOf(27), stored.gathered.get("item:1511"));

        Trip restored = SessionMapper.toTrip(stored);
        assertEquals(Integer.valueOf(27), restored.gathered().get(ItemKey.item(1511)));
    }

    @Test
    public void toTripTreatsMissingGatheredAsEmpty() {
        StoredTrip stored = SessionMapper.toStored(sampleTrip(), new HashMap<>());
        stored.gathered = null; // simulate a session saved before the feature existed
        Trip restored = SessionMapper.toTrip(stored);
        assertTrue(restored.gathered().isEmpty());
    }
}

package com.sessiontracker.adapter;

import static org.junit.Assert.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import org.junit.Test;

public class SessionStoreTest {

    private StoredSession sampleSession(String id, String accountHash) {
        StoredTrip trip = new StoredTrip();
        trip.id = "trip-1";
        trip.startMillis = 0;
        trip.endMillis = 60_000;
        trip.died = false;
        trip.kills = new HashMap<>();
        trip.kills.put("Demonic gorilla", 2);
        trip.dropped = new HashMap<>();
        trip.pickedUp = new HashMap<>();
        trip.missed = new HashMap<>();
        trip.suppliesUsed = new HashMap<>();
        trip.xpGained = new HashMap<>();
        trip.unitPrices = new HashMap<>();
        trip.dropped.put("item:560", 100);

        StoredSession session = new StoredSession();
        session.id = id;
        session.accountHash = accountHash;
        session.category = "Demonic Gorillas";
        session.name = "evening";
        session.startMillis = 0;
        session.endMillis = 60_000;
        session.trips = new ArrayList<>();
        session.trips.add(trip);
        return session;
    }

    @Test
    public void savesAndLoadsASessionPerAccount() throws Exception {
        Path root = Files.createTempDirectory("grt-store");
        SessionStore store = new SessionStore(root, new com.google.gson.Gson());

        store.save(sampleSession("s1", "acct-A"));

        List<StoredSession> loaded = store.load("acct-A");
        assertEquals(1, loaded.size());
        StoredSession s = loaded.get(0);
        assertEquals("s1", s.id);
        assertEquals("Demonic Gorillas", s.category);
        assertEquals(1, s.trips.size());
        assertEquals(Integer.valueOf(100), s.trips.get(0).dropped.get("item:560"));
    }

    @Test
    public void loadIsolatesByAccount() throws Exception {
        Path root = Files.createTempDirectory("grt-store");
        SessionStore store = new SessionStore(root, new com.google.gson.Gson());
        store.save(sampleSession("s1", "acct-A"));
        store.save(sampleSession("s2", "acct-B"));

        assertEquals(1, store.load("acct-A").size());
        assertEquals(1, store.load("acct-B").size());
    }

    @Test
    public void loadOfUnknownAccountIsEmpty() throws Exception {
        Path root = Files.createTempDirectory("grt-store");
        SessionStore store = new SessionStore(root, new com.google.gson.Gson());
        assertTrue(store.load("nobody").isEmpty());
    }

    @Test
    public void loadSkipsCorruptFilesAndReturnsTheValidOnes() throws Exception {
        java.nio.file.Path root = java.nio.file.Files.createTempDirectory("grt-store");
        SessionStore store = new SessionStore(root, new com.google.gson.Gson());
        store.save(sampleSession("good", "acct-A"));

        // Write a corrupt JSON file alongside the good one in the same account dir.
        java.nio.file.Path dir = root.resolve("acct-A");
        java.nio.file.Files.write(dir.resolve("broken.json"),
                "{ this is not valid json".getBytes(java.nio.charset.StandardCharsets.UTF_8));

        java.util.List<StoredSession> loaded = store.load("acct-A");
        assertEquals(1, loaded.size());
        assertEquals("good", loaded.get(0).id);
    }

    @Test
    public void loadIgnoresNonJsonFiles() throws Exception {
        java.nio.file.Path root = java.nio.file.Files.createTempDirectory("grt-store");
        SessionStore store = new SessionStore(root, new com.google.gson.Gson());
        store.save(sampleSession("good", "acct-A"));
        java.nio.file.Path dir = root.resolve("acct-A");
        java.nio.file.Files.write(dir.resolve("notes.txt"),
                "hello".getBytes(java.nio.charset.StandardCharsets.UTF_8));

        assertEquals(1, store.load("acct-A").size());
    }

    @Test
    public void deleteRemovesOnlyTheNamedSession() throws Exception {
        Path root = Files.createTempDirectory("grt-store");
        SessionStore store = new SessionStore(root, new com.google.gson.Gson());
        store.save(sampleSession("s1", "acct-A"));
        store.save(sampleSession("s2", "acct-A"));

        store.delete("acct-A", "s1");

        List<StoredSession> loaded = store.load("acct-A");
        assertEquals(1, loaded.size());
        assertEquals("s2", loaded.get(0).id);
    }

    @Test
    public void deleteOfMissingSessionIsANoOp() throws Exception {
        Path root = Files.createTempDirectory("grt-store");
        SessionStore store = new SessionStore(root, new com.google.gson.Gson());
        store.save(sampleSession("s1", "acct-A"));

        store.delete("acct-A", "does-not-exist");

        assertEquals(1, store.load("acct-A").size());
    }

    @Test
    public void loadServesSavesAndDeletesWithoutAliasingTheSavedObject() throws Exception {
        Path root = Files.createTempDirectory("grt-store");
        SessionStore store = new SessionStore(root, new com.google.gson.Gson());
        StoredSession live = sampleSession("s1", "acct-A");
        store.save(live);

        // Mutating the caller's object after saving must not leak into what load returns.
        live.name = "changed after save";
        live.trips.clear();
        StoredSession loaded = store.load("acct-A").get(0);
        assertEquals("evening", loaded.name);
        assertEquals(1, loaded.trips.size());

        // Saving the same id again replaces rather than duplicates.
        live.name = "renamed";
        store.save(live);
        assertEquals(1, store.load("acct-A").size());
        assertEquals("renamed", store.load("acct-A").get(0).name);

        store.delete("acct-A", "s1");
        assertTrue(store.load("acct-A").isEmpty());
        assertFalse(Files.exists(root.resolve("acct-A").resolve("s1.json")));
    }

    @Test
    public void loadReturnsAnIndependentList() throws Exception {
        Path root = Files.createTempDirectory("grt-store");
        SessionStore store = new SessionStore(root, new com.google.gson.Gson());
        store.save(sampleSession("s1", "acct-A"));

        store.load("acct-A").clear();

        assertEquals(1, store.load("acct-A").size());
    }
}

