/** Renders the Sessions tab headless over a seeded store and drives it like a user would. */
public class SessionsTabTest {

    private static final long START = 1_700_000_000_000L;

    private SessionStore store;
    private SessionHistory history;
    private SessionsTab tab;

    @Before
    public void setUp() throws Exception {
        store = new SessionStore(Files.createTempDirectory("sessions-tab-test"), new Gson());
        history = new SessionHistory(store, "42", Fixtures::itemName);
        tab = new SessionsTab(Swing.inlineClientThread(), Collections.emptyMap(), new RecordingIcons(false));

        // Two 30-minute Vorkath trips an hour apart end to end; a shorter, older woodcutting session.
        store.save(session("vork", "Vorkath", "", START,
                trip("v1", START, START + 30 * MINUTE).kills("Vorkath", 5)
                        .pickedUp(COINS, 100_000, 1).xp("Ranged", 12_000).build(),
                trip("v2", START + 30 * MINUTE, START + 60 * MINUTE).kills("Vorkath", 4)
                        .pickedUp(COINS, 50_000, 1).xp("Ranged", 9_000).build()));
        store.save(session("oaks", "Oak logs", "Evening chop", START - 24 * 60 * MINUTE,
                trip("o1", START - 24 * 60 * MINUTE, START - 24 * 60 * MINUTE + 30 * MINUTE)
                        .gathered(OAK_LOGS, 100, 20).xp("Woodcutting", 3_750).build()));
    }

    private void show() throws Exception {
        onEdt(() -> tab.setContext(null, history));
        flushEdt();
    }

    @Test
    public void listsSessionsNewestFirstWithTripsDurationAndNet() throws Exception {
        show();

        List<String> visible = texts(tab);
        int vorkath = visible.indexOf("Vorkath");
        int oaks = visible.indexOf("Evening chop"); // a named session shows its name, not its category
        assertTrue("Vorkath row missing: " + visible, vorkath >= 0);
        assertTrue("newest session should be listed first: " + visible, vorkath < oaks);
        assertHasText(tab, "2 trips · 1h 0m · ");
        assertHasText(tab, "150.0K");
        assertHasText(tab, "1 trip · 30m · ");
        assertHasText(tab, "2.0K");
    }

    @Test
    public void expandingASessionShowsItsSummaryAndTrips() throws Exception {
        show();
        assertNoText(tab, "Trip 1");

        press(label(tab, "Vorkath"));
        flushEdt();

        assertHasText(tab, "Avg net / trip");
        assertHasText(tab, "75.0K");
        assertHasText(tab, "Avg kills / trip");
        assertHasText(tab, "4.5");
        assertHasText(tab, "Trip 1 · 30m · 5 kills · ");
        assertHasText(tab, "Trip 2 · 30m · 4 kills · ");
        assertHasText(tab, "100.0K");
        assertHasText(tab, "50.0K");

        press(label(tab, "Vorkath")); // collapses again
        flushEdt();
        assertNoText(tab, "Trip 1");
    }

    @Test
    public void openingATripShowsItsDetailAndBackReturnsToTheList() throws Exception {
        show();
        press(label(tab, "Vorkath"));
        flushEdt();

        press(label(tab, "Trip 1 · 30m · 5 kills · "));
        flushEdt();

        assertHasText(tab, "Net profit");
        assertHasText(tab, "Duration");
        assertHasText(tab, "30m");
        assertHasText(tab, "KILLS"); // section headers render uppercased
        assertHasText(tab, "PICKED UP");
        assertHasText(tab, "Coins ×100000");
        assertHasText(tab, "Ranged");
        assertHasText(tab, "12.0K");
        assertNoText(tab, "Evening chop"); // the list is hidden behind the detail card

        click(button(tab, "Back"));
        flushEdt();
        assertHasText(tab, "Evening chop");
    }

    @Test
    public void tripDetailDrawsItemIconsWithTheQuantityInsteadOfTextRows() throws Exception {
        RecordingIcons icons = new RecordingIcons(true);
        tab = new SessionsTab(Swing.inlineClientThread(), Collections.emptyMap(), icons);
        show();
        press(label(tab, "Vorkath"));
        flushEdt();
        press(label(tab, "Trip 1 · 30m · 5 kills · "));
        flushEdt();

        assertEquals("100K", icons.quantityOn(COINS));
        assertNoText(tab, "Coins ×100000");
        Swing.assertHasTooltip(tab, "Coins");
    }

    @Test
    public void editingRenamesAndRecategorizesTheSession() throws Exception {
        show();

        click(findAll(tab, javax.swing.JButton.class, b -> "Edit".equals(b.getText())).get(0));
        flushEdt();
        List<JTextField> fields = findAll(tab, JTextField.class, f -> true);
        assertEquals("expected name and category fields", 2, fields.size());
        onEdt(() -> {
            fields.get(0).setText("Bird night");
            fields.get(1).setText("Vorkath (ranged)");
        });
        click(button(tab, "Save"));
        flushEdt();

        SessionHistory.SessionSummary edited = history.sessionsNewestFirst().get(0);
        assertEquals("Bird night", edited.name);
        assertEquals("Vorkath (ranged)", edited.category);
        assertHasText(tab, "Bird night");
    }

    @Test
    public void finishedSessionsOfferResumeWhileLoggedIn() throws Exception {
        TrackingService service = mock(TrackingService.class);
        when(service.activeSessionId()).thenReturn("oaks"); // the woodcutting session is running
        onEdt(() -> tab.setContext(service, history));
        flushEdt();

        press(label(tab, "Vorkath"));
        flushEdt();
        click(button(tab, "Resume session"));
        flushEdt();
        verify(service).resumeSession("vork");

        // The running session itself cannot be resumed.
        press(label(tab, "Evening chop"));
        flushEdt();
        assertNoText(tab, "Resume session");
    }

    @Test
    public void resumeIsNotOfferedWhenLoggedOut() throws Exception {
        show(); // no service
        press(label(tab, "Vorkath"));
        flushEdt();
        assertNoText(tab, "Resume session");
    }
}

package com.sessiontracker.adapter.runelite;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.OptionalInt;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/** Each opaque container, and the message the game prints as it swallows something. */
public class StashBagsTest {

    private static OptionalInt credit(int openItemId, String message) {
        return StashBags.byOpenItemId(openItemId)
                .map(bag -> bag.match(message))
                .orElse(OptionalInt.empty());
    }

    @Test
    public void coalBagTakesMinedCoal() {
        assertEquals(OptionalInt.of(ItemID.COAL),
                credit(ItemID.COAL_BAG_OPEN, "You manage to mine some coal."));
    }

    @Test
    public void gemBagTakesAMinedGem() {
        assertEquals(OptionalInt.of(ItemID.UNCUT_SAPPHIRE),
                credit(ItemID.GEM_BAG_OPEN, "You just found a Sapphire!"));
    }

    @Test
    public void gemSackTakesTheGemsOnlyItHolds() {
        assertEquals(OptionalInt.of(ItemID.UNCUT_JADE),
                credit(ItemID.GEM_SACK_OPEN, "You just mined a piece of Jade!"));
    }

    @Test
    public void herbSackTakesAHerbPickedUp() {
        assertEquals(OptionalInt.of(ItemID.UNIDENTIFIED_RANARR),
                credit(ItemID.SLAYER_HERB_SACK_OPEN,
                        "You put the Grimy ranarr herb into your herb sack."));
    }

    @Test
    public void fishBarrelTakesACaughtFish() {
        assertEquals(OptionalInt.of(ItemID.RAW_SHARK),
                credit(ItemID.FISH_BARREL_OPEN, "You catch a shark."));
    }

    @Test
    public void logBasketTakesChoppedLogsAndKeepsTheTreeApart() {
        assertEquals(OptionalInt.of(ItemID.YEW_LOGS),
                credit(ItemID.LOG_BASKET_OPEN, "You get some yew logs."));
        assertEquals(OptionalInt.of(ItemID.LOGS),
                credit(ItemID.LOG_BASKET_OPEN, "You get some logs."));
    }

    @Test
    public void aClosedBagIsNotOpenSoNothingIsCredited() {
        assertFalse(StashBags.byOpenItemId(ItemID.COAL_BAG).isPresent());
    }

    @Test
    public void aMessageFromAnotherSkillIsIgnored() {
        assertFalse(credit(ItemID.COAL_BAG_OPEN, "You get some yew logs.").isPresent());
    }

    @Test
    public void anyFormOfABagIsRecognisedSoAManualTransferCanForgetIt() {
        assertTrue(StashBags.byAnyItemId(ItemID.COAL_BAG).isPresent());
        assertTrue(StashBags.byAnyItemId(ItemID.COAL_BAG_OPEN).isPresent());
        assertEquals(StashBags.byAnyItemId(ItemID.COAL_BAG).get().name(),
                StashBags.byAnyItemId(ItemID.COAL_BAG_OPEN).get().name());
    }
}

