        SessionStore store = new SessionStore(Files.createTempDirectory("stats-tab-test"), new Gson());
        history = new SessionHistory(store, "42", Fixtures::itemName);
        tab = new StatsTab(Swing.inlineClientThread(), new RecordingIcons(false));

        // Vorkath: 150K over one hour of wall clock, 2 sharks per trip. Oak logs: 2K over 30 minutes.
        store.save(session("vork", "Vorkath", "", START,
                trip("v1", START, START + 30 * MINUTE).kills("Vorkath", 5)
                        .pickedUp(COINS, 100_000, 1).supplies(SHARK, 2, 500).xp("Ranged", 12_000).build(),
                trip("v2", START + 30 * MINUTE, START + 60 * MINUTE).kills("Vorkath", 4)
                        .pickedUp(COINS, 50_000, 1).supplies(SHARK, 2, 500).xp("Ranged", 9_000).build()));
        store.save(session("oaks", "Oak logs", "", START - 24 * 60 * MINUTE,
                trip("o1", START - 24 * 60 * MINUTE, START - 24 * 60 * MINUTE + 30 * MINUTE)
                        .gathered(OAK_LOGS, 100, 20).xp("Woodcutting", 3_750).build()));
    }

    private void show() throws Exception {
        onEdt(() -> tab.setHistory(history));
        flushEdt();
    }

    @Test
    public void showsOneCardPerCategoryOrderedByGpPerHour() throws Exception {
        show();

        List<String> visible = texts(tab);
        int vorkath = visible.indexOf("Vorkath");
        int oaks = visible.indexOf("Oak logs");
        assertTrue("Vorkath card missing: " + visible, vorkath >= 0);
        assertTrue("Oak logs card missing: " + visible, oaks >= 0);
        assertTrue("higher GP/hr category should come first: " + visible, vorkath < oaks);
        assertHasText(tab, "1 session · 2 trips");
        assertHasText(tab, "1 session · 1 trip");
        assertHasText(tab, "148.0K"); // (150,000 - 4 × 500) gp over one hour
        assertHasText(tab, "4.0K");   // 2,000 gp over half an hour
    }

    @Test
    public void averageIconsKeepTheDecimalSoTwoAndAHalfSharksIsVisible() throws Exception {
        RecordingIcons icons = new RecordingIcons(true);
        tab = new StatsTab(Swing.inlineClientThread(), icons);
        show();

        press(label(tab, "Vorkath"));
        flushEdt();

        assertEquals("2.0", icons.quantityOn(SHARK));
        assertEquals("75000", icons.quantityOn(COINS));
    }

    @Test
    public void openingACategoryShowsItsAveragesAndBackReturnsToTheCards() throws Exception {
        show();

        press(label(tab, "Vorkath"));
        flushEdt();

        assertHasText(tab, "PER HOUR"); // section headers render uppercased
        assertHasText(tab, "PER-TRIP AVERAGES");
        assertHasText(tab, "74.0K");   // avg net per trip: (150,000 - 2,000) / 2
        assertHasText(tab, "Trip length");
        assertHasText(tab, "30m");
        assertHasText(tab, "PER SESSION");
        assertHasText(tab, "Avg session length");
        assertHasText(tab, "1h 0m");
        assertHasText(tab, "XP AVERAGES");
        assertHasText(tab, "Ranged");
        assertHasText(tab, "KILL AVERAGES");
        assertNoText(tab, "Oak logs");

        click(button(tab, "Back"));
        flushEdt();
        assertHasText(tab, "Oak logs");
    }
}

package com.sessiontracker.adapter.runelite;

import static org.junit.Assert.fail;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;

import java.awt.Component;
import java.awt.Container;
import java.awt.event.MouseEvent;
import java.awt.event.MouseListener;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;
import javax.swing.AbstractButton;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import javax.swing.text.JTextComponent;
import net.runelite.client.callback.ClientThread;

/**
 * Headless Swing helpers for panel tests: run work on the EDT, read the visible text out of a
 * component tree, and drive buttons and clickable rows the way a user would.
 */
final class Swing {

    private Swing() {
    }

    /** Wait for everything already queued on the EDT (e.g. panel refreshes) to finish. */
    static void flushEdt() throws Exception {
        SwingUtilities.invokeAndWait(() -> { });
    }

    static void onEdt(Runnable r) throws Exception {
        SwingUtilities.invokeAndWait(r);
    }

    /** A ClientThread whose {@code invoke(Runnable)} runs the task immediately on the caller. */
    static ClientThread inlineClientThread() {
        ClientThread clientThread = mock(ClientThread.class);
        doAnswer(invocation -> {
            ((Runnable) invocation.getArgument(0)).run();
            return null;
        }).when(clientThread).invoke(any(Runnable.class));
        return clientThread;
    }

    /** Every non-empty label, button and text-field string in the visible part of the tree, in order. */
    static List<String> texts(Component root) {
        List<String> out = new ArrayList<>();
        collect(root, out);
        return out;
    }

    private static void collect(Component c, List<String> out) {
        if (!c.isVisible()) {
            return;
        }
        String text = null;
        if (c instanceof JLabel) {
            text = ((JLabel) c).getText();
        } else if (c instanceof AbstractButton) {
            text = ((AbstractButton) c).getText();
        } else if (c instanceof JTextComponent) {
            text = ((JTextComponent) c).getText();
        }
        if (text != null && !text.isEmpty()) {
            out.add(text);
        }
        if (c instanceof Container) {
            for (Component child : ((Container) c).getComponents()) {
                collect(child, out);
            }
        }
    }

    /** Every tooltip in the visible part of the tree, in order. */
    static List<String> tooltips(Component root) {
        List<String> out = new ArrayList<>();
        collectTooltips(root, out);
        return out;
    }

    private static void collectTooltips(Component c, List<String> out) {
        if (!c.isVisible()) {
            return;
        }
        if (c instanceof javax.swing.JComponent) {
            String tip = ((javax.swing.JComponent) c).getToolTipText();
            if (tip != null && !tip.isEmpty()) {
                out.add(tip);
            }
        }
        if (c instanceof Container) {
            for (Component child : ((Container) c).getComponents()) {
                collectTooltips(child, out);
            }
        }
    }

    static void assertHasTooltip(Component root, String needle) {
        for (String t : tooltips(root)) {
            if (t.contains(needle)) {
                return;
            }
        }
        fail("Expected a tooltip containing \"" + needle + "\" but they were " + tooltips(root));
    }

    static boolean hasText(Component root, String needle) {
        for (String t : texts(root)) {
            if (t.contains(needle)) {
                return true;
            }
        }
        return false;
    }

    static void assertHasText(Component root, String needle) {
        if (!hasText(root, needle)) {
            fail("Expected text containing \"" + needle + "\" but the visible texts were " + texts(root));
        }
    }

    static void assertNoText(Component root, String needle) {
        if (hasText(root, needle)) {
            fail("Did not expect text containing \"" + needle + "\" but the visible texts were " + texts(root));
        }
    }

    static <T extends Component> List<T> findAll(Component root, Class<T> type, Predicate<T> filter) {
        List<T> out = new ArrayList<>();
        findInto(root, type, filter, out);
        return out;
    }

    private static <T extends Component> void findInto(Component c, Class<T> type, Predicate<T> filter,
                                                       List<T> out) {
        if (!c.isVisible()) {
            return;
        }
        if (type.isInstance(c) && filter.test(type.cast(c))) {
            out.add(type.cast(c));
        }
        if (c instanceof Container) {
            for (Component child : ((Container) c).getComponents()) {
                findInto(child, type, filter, out);
            }
        }
    }

    static <T extends Component> T find(Component root, Class<T> type, Predicate<T> filter) {
        List<T> all = findAll(root, type, filter);
        if (all.isEmpty()) {
            fail("No visible " + type.getSimpleName() + " matched; visible texts were " + texts(root));
        }
        return all.get(0);
    }

    static JLabel label(Component root, String exactText) {
        return find(root, JLabel.class, l -> exactText.equals(l.getText()));
    }

    static JButton button(Component root, String exactText) {
        return find(root, JButton.class, b -> exactText.equals(b.getText()));
    }

    /** Click a button on the EDT, as a user would. */
    static void click(JButton button) throws Exception {
        onEdt(() -> button.doClick(0));
    }

    /** Press on a component wired with {@link Styles#clickable}: fires its mouse listeners on the EDT. */
    static void press(Component c) throws Exception {
        onEdt(() -> {
            MouseEvent e = new MouseEvent(c, MouseEvent.MOUSE_PRESSED, System.currentTimeMillis(),
                    0, 1, 1, 1, false, MouseEvent.BUTTON1);
            for (MouseListener l : c.getMouseListeners()) {
                l.mousePressed(e);
            }
        });
    }
}

package com.sessiontracker.adapter.runelite;

import static org.junit.Assert.assertEquals;

import java.awt.Dimension;
import java.awt.FlowLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import org.junit.Test;

/** The wrapping grid has to report every row's height, or its last row gets clipped away. */
public class WrapLayoutTest {

    private static JPanel gridOf(int cells, int parentWidth) {
        JPanel parent = new JPanel();
        parent.setSize(parentWidth, 500);
        JPanel grid = new JPanel(new WrapLayout(FlowLayout.LEFT, 2, 2));
        parent.add(grid);
        for (int i = 0; i < cells; i++) {
            JLabel cell = new JLabel();
            cell.setPreferredSize(new Dimension(38, 34));
            grid.add(cell);
        }
        return grid;
    }

    @Test
    public void countsEveryRowBeforeTheGridItselfHasBeenSized() {
        // Five 38px cells fit across 207px, so seven of them need a second row.
        JPanel grid = gridOf(7, 207);

        assertEquals(74, grid.getPreferredSize().height);
    }

    @Test
    public void asingleRowIsStillOneRowTall() {
        JPanel grid = gridOf(3, 207);

        assertEquals(38, grid.getPreferredSize().height);
    }
}

package com.sessiontracker.core;

import static org.junit.Assert.*;
import com.sessiontracker.core.item.ItemKey;
import com.sessiontracker.core.item.ItemValuer;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class CategoryAggregatorTest {

    private final ItemValuer oneGp = (key, qty) -> qty;

    private Trip trip(String id, long start, long end, int net, int kills) {
        Map<ItemKey, Integer> picked = new HashMap<>();
        picked.put(ItemKey.item(995), net);
        Map<String, Integer> killMap = new HashMap<>();
        killMap.put("Demonic gorilla", kills);
        return new Trip(id, start, end, false, killMap, new HashMap<>(),
                picked, new HashMap<>(), new HashMap<>(), new HashMap<>());
    }

    private Session session(String id, String category, Trip... trips) {
        return new Session(id, "acct", category, "", Arrays.asList(trips));
    }

    @Test
    public void aggregatesPerTripAveragesAndTimeWeightedRate() {
        Session s1 = session("s1", "Demonic Gorillas",
                trip("a", 0, 1_800_000, 100, 20),
                trip("b", 1_800_000, 3_600_000, 300, 30));
        CategoryStats stats = CategoryStats.from("Demonic Gorillas", Arrays.asList(s1), oneGp);

        assertEquals(1, stats.sessionCount());
        assertEquals(2, stats.tripCount());
        // 400 gp over 1 hour wall-clock
        assertEquals(400, stats.gpPerHour());
        // avg net per trip = (100 + 300) / 2
        assertEquals(200, stats.avgNetProfitPerTrip());
        // avg kills per trip = (20 + 30) / 2
        assertEquals(25.0, stats.avgKillsPerTrip(), 0.0001);
    }

    @Test
    public void gpPerHourIsTimeWeightedAcrossSessions() {
        // Session A: 100 gp over 1h -> 100/h ; Session B: 1000 gp over 0.5h -> 2000/h.
        // A naive average of per-session rates would be 1050; the time-weighted rate
        // is total 1100 gp / 1.5h = 733.
        Session a = session("a", "Cat", trip("a1", 0, 3_600_000, 100, 0));
        Session b = session("b", "Cat", trip("b1", 0, 1_800_000, 1000, 0));
        CategoryStats stats = CategoryStats.from("Cat", Arrays.asList(a, b), oneGp);
        assertEquals(2, stats.sessionCount());
        assertEquals(2, stats.tripCount());
        assertEquals(733, stats.gpPerHour());
        assertEquals(550, stats.avgNetProfitPerTrip());
    }

    @Test
    public void averagesSuppliesPerTripPerItem() {
        ItemKey shark = ItemKey.item(385);
        Map<ItemKey, Integer> s1Supplies = new HashMap<>();
        s1Supplies.put(shark, 4);
        Trip a = new Trip("a", 0, 1_800_000, false, new HashMap<>(), new HashMap<>(),
                new HashMap<>(), new HashMap<>(), s1Supplies, new HashMap<>());
        Map<ItemKey, Integer> s2Supplies = new HashMap<>();
        s2Supplies.put(shark, 2);
        Trip b = new Trip("b", 1_800_000, 3_600_000, false, new HashMap<>(), new HashMap<>(),
                new HashMap<>(), new HashMap<>(), s2Supplies, new HashMap<>());
        Session sess = new Session("s1", "acct", "Cat", "", Arrays.asList(a, b));
        CategoryStats stats = CategoryStats.from("Cat", Arrays.asList(sess), oneGp);
        // (4 + 2) / 2 trips = 3.0 sharks per trip
        assertEquals(3.0, stats.avgSuppliesPerTrip().get(shark), 0.0001);
    }

    @Test
    public void aggregateValuesEachTripWithItsOwnValuer() {
        java.util.Map<com.sessiontracker.core.item.ItemKey, Integer> picked = new java.util.HashMap<>();
        picked.put(com.sessiontracker.core.item.ItemKey.item(560), 10);
        Trip a = new Trip("a", 0, 3_600_000L, false, new java.util.HashMap<>(),
                new java.util.HashMap<>(), new java.util.HashMap<>(picked), new java.util.HashMap<>(),
                new java.util.HashMap<>(), new java.util.HashMap<>());
        Trip b = new Trip("b", 3_600_000L, 7_200_000L, false, new java.util.HashMap<>(),
                new java.util.HashMap<>(), new java.util.HashMap<>(picked), new java.util.HashMap<>(),
                new java.util.HashMap<>(), new java.util.HashMap<>());
        Session s = new Session("s", "acct", "Vorkath", "name", java.util.Arrays.asList(a, b));

        java.util.function.Function<Trip, com.sessiontracker.core.item.ItemValuer> perTrip =
                t -> (key, qty) -> (t.id().equals("a") ? 2L : 5L) * qty;

        java.util.Map<String, CategoryStats> out =
                CategoryAggregator.aggregate(java.util.Arrays.asList(s), perTrip);
        CategoryStats stats = out.get("Vorkath");
        assertEquals(2, stats.tripCount());
        assertEquals(35L, stats.avgNetProfitPerTrip());
    }

    @Test
    public void groupsSessionsByCategory() {
        Session a = session("s1", "Vorkath", trip("a", 0, 3_600_000, 1000, 5));
        Session b = session("s2", "Zulrah", trip("b", 0, 3_600_000, 2000, 1));
        Map<String, CategoryStats> grouped =
                CategoryAggregator.aggregate(Arrays.asList(a, b), oneGp);
        assertEquals(2, grouped.size());
        assertEquals(1000, grouped.get("Vorkath").gpPerHour());
        assertEquals(2000, grouped.get("Zulrah").gpPerHour());
    }

    @Test
    public void averageSessionDurationIsWallClockPerSession() {
        Session a = session("a", "Cat", trip("a1", 0, 3_600_000, 100, 0)); // 1h wall clock
        Session b = session("b", "Cat", trip("b1", 0, 1_800_000, 100, 0)); // 0.5h wall clock
        CategoryStats stats = CategoryStats.from("Cat", Arrays.asList(a, b), oneGp);
        // (3_600_000 + 1_800_000) / 2 sessions
        assertEquals(2_700_000L, stats.avgSessionDurationMillis());
    }

    @Test
    public void averageSessionDurationIsZeroWithNoSessions() {
        CategoryStats stats = CategoryStats.from("Cat", java.util.Collections.emptyList(), oneGp);
        assertEquals(0L, stats.avgSessionDurationMillis());
    }
}

package com.sessiontracker.core;

import static org.junit.Assert.*;
import com.sessiontracker.core.item.ItemKey;
import com.sessiontracker.core.item.ItemValuer;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class SessionTest {

    private final ItemValuer oneGp = (key, qty) -> qty;

    private Trip tripWithProfitAndXp(String id, long start, long end, int net, long xp) {
        Map<ItemKey, Integer> picked = new HashMap<>();
        picked.put(ItemKey.item(995), net); // net gp == net at 1gp each, no supplies
        Map<String, Long> xpMap = new HashMap<>();
        xpMap.put("RANGED", xp);
        return new Trip(id, start, end, false, new HashMap<>(), new HashMap<>(),
                picked, new HashMap<>(), new HashMap<>(), xpMap);
    }

    @Test
    public void wallClockSpansFirstStartToLastEnd() {
        Trip a = tripWithProfitAndXp("a", 0, 600_000, 100, 1000);
        Trip b = tripWithProfitAndXp("b", 900_000, 1_800_000, 200, 2000);
        Session session = new Session("s1", "acct", "Vorkath", "evening", Arrays.asList(a, b));
        assertEquals(1_800_000, session.wallClockMillis()); // includes the 5-min bank gap
    }

    @Test
    public void gpPerHourUsesWallClockIncludingGaps() {
        Trip a = tripWithProfitAndXp("a", 0, 600_000, 100, 0);
        Trip b = tripWithProfitAndXp("b", 900_000, 1_800_000, 200, 0);
        Session session = new Session("s1", "acct", "Vorkath", "evening", Arrays.asList(a, b));
        // 300 gp over half an hour -> 600 gp/hr
        assertEquals(600, session.gpPerHour(oneGp));
    }

    @Test
    public void xpPerHourUsesWallClock() {
        Trip a = tripWithProfitAndXp("a", 0, 1_800_000, 0, 30_000);
        Session session = new Session("s1", "acct", "Vorkath", "evening", Arrays.asList(a));
        assertEquals(60_000, session.xpPerHour()); // 30k xp over 30 min
    }

    @Test
    public void gpPerHourValuesEachTripWithItsOwnValuer() {
        java.util.Map<com.sessiontracker.core.item.ItemKey, Integer> picked = new java.util.HashMap<>();
        picked.put(com.sessiontracker.core.item.ItemKey.item(560), 10);
        Trip a = new Trip("a", 0, 3_600_000L, false, new java.util.HashMap<>(),
                new java.util.HashMap<>(), new java.util.HashMap<>(picked), new java.util.HashMap<>(),
                new java.util.HashMap<>(), new java.util.HashMap<>());
        Trip b = new Trip("b", 3_600_000L, 7_200_000L, false, new java.util.HashMap<>(),
                new java.util.HashMap<>(), new java.util.HashMap<>(picked), new java.util.HashMap<>(),
                new java.util.HashMap<>(), new java.util.HashMap<>());
        Session s = new Session("s", "acct", "cat", "name", java.util.Arrays.asList(a, b));

        java.util.function.Function<Trip, com.sessiontracker.core.item.ItemValuer> perTrip =
                t -> (key, qty) -> (t.id().equals("a") ? 2L : 5L) * qty;

        assertEquals(70L, s.totalNetProfit(perTrip));
        assertEquals(35L, s.gpPerHour(perTrip));
    }

    @Test
    public void categoryAndNameAreEditable() {
        Session session = new Session("s1", "acct", "Vorkath", "evening",
                Arrays.asList(tripWithProfitAndXp("a", 0, 1000, 0, 0)));
        session.setCategory("Zulrah");
        session.setName("alt grind");
        assertEquals("Zulrah", session.category());
        assertEquals("alt grind", session.name());
    }

    @Test
    public void wallClockExcludesPausedTime() {
        Trip a = tripWithProfitAndXp("a", 0, 600_000, 100, 0);
        Trip b = tripWithProfitAndXp("b", 7_800_000, 8_400_000, 200, 0); // resumed two hours later
        Session session = new Session("s1", "acct", "Vorkath", "evening", Arrays.asList(a, b),
                7_200_000);
        assertEquals(1_200_000, session.wallClockMillis()); // 10 + 10 minutes, gap excluded
        assertEquals(900, session.gpPerHour(oneGp));         // 300 gp over 20 minutes
    }
}

package com.sessiontracker.core;

import static org.junit.Assert.*;
import com.sessiontracker.core.item.ItemKey;
import com.sessiontracker.core.item.ItemValuer;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class TripLedgerTest {

    private static Map<ItemKey, Integer> carried(Object... pairs) {
        Map<ItemKey, Integer> m = new HashMap<>();
        for (int i = 0; i < pairs.length; i += 2) {
            m.put((ItemKey) pairs[i], (Integer) pairs[i + 1]);
        }
        return m;
    }

    // Values 1gp per unit of everything, so value == quantity. Keeps assertions simple.
    private final ItemValuer oneGp = (key, qty) -> qty;

    @Test
    public void countsKillsAndDroppedLoot() {
        TripLedger ledger = new TripLedger();
        ledger.recordKill("Demonic gorilla", carried(ItemKey.item(560), 100));
        ledger.recordKill("Demonic gorilla", carried(ItemKey.item(560), 50));
        Trip trip = ledger.build("t1", 0, 60_000, false);
        assertEquals(2, trip.totalKills());
        assertEquals(Integer.valueOf(150), trip.dropped().get(ItemKey.item(560)));
    }

    @Test
    public void pickedUpDrainsGroundPoolAndLeavesMissed() {
        TripLedger ledger = new TripLedger();
        ledger.updateCarried(carried()); // tick 0: empty start
        ledger.recordKill("Demonic gorilla", carried(ItemKey.item(560), 100));
        ledger.updateCarried(carried(ItemKey.item(560), 60)); // picked up 60 of the 100
        Trip trip = ledger.build("t1", 0, 60_000, false);
        assertEquals(Integer.valueOf(60), trip.pickedUp().get(ItemKey.item(560)));
        assertEquals(Integer.valueOf(40), trip.missed().get(ItemKey.item(560)));
    }

    @Test
    public void rebaselineAbsorbsDepositsWithoutCountingThemAsSupplies() {
        TripLedger ledger = new TripLedger();
        ledger.updateCarried(carried());                       // baseline empty
        ledger.updateCarried(carried(ItemKey.item(1521), 28)); // gathered 28 oak logs
        ledger.rebaseline(carried());                          // banked all 28 (deposit)
        ledger.updateCarried(carried(ItemKey.item(1521), 1));  // chopped 1 more after the bank
        Trip trip = ledger.build("t1", 0, 60_000, false);
        assertEquals(Integer.valueOf(29), trip.gathered().get(ItemKey.item(1521))); // deposit ignored, 28+1
        assertTrue(trip.suppliesUsed().isEmpty());
    }

    @Test
    public void rebaselineAbsorbsWithdrawalsWithoutCountingThemAsGathered() {
        TripLedger ledger = new TripLedger();
        ledger.updateCarried(carried());                       // baseline empty
        ledger.rebaseline(carried(ItemKey.item(385), 3));      // withdrew 3 sharks at the bank
        ledger.updateCarried(carried(ItemKey.item(385), 1));   // ate 2 after leaving
        Trip trip = ledger.build("t1", 0, 60_000, false);
        assertNull(trip.gathered().get(ItemKey.item(385)));    // withdrawal not gathered
        assertEquals(Integer.valueOf(2), trip.suppliesUsed().get(ItemKey.item(385))); // brought food eaten
    }

    @Test
    public void netDecreaseIsCountedAsSuppliesUsed() {
        TripLedger ledger = new TripLedger();
        ledger.updateCarried(carried(ItemKey.item(385), 4)); // start: 4 sharks
        ledger.updateCarried(carried(ItemKey.item(385), 1)); // ate 3
        Trip trip = ledger.build("t1", 0, 60_000, false);
        assertEquals(Integer.valueOf(3), trip.suppliesUsed().get(ItemKey.item(385)));
    }

    @Test
    public void overlappingLootAndSupplyAreBothCounted() {
        // Drink one of your own prayer doses on one tick, loot a (4) on a later tick.
        ItemKey prayer = ItemKey.potion("Prayer potion");
        TripLedger ledger = new TripLedger();
        ledger.updateCarried(carried(prayer, 12)); // start: 3 x (4) = 12 doses
        ledger.updateCarried(carried(prayer, 11)); // drank 1 dose -> supplies +1
        ledger.recordKill("Demonic gorilla", carried(prayer, 4)); // drop a (4)
        ledger.updateCarried(carried(prayer, 15)); // picked up 4 doses
        Trip trip = ledger.build("t1", 0, 60_000, false);
        assertEquals(Integer.valueOf(1), trip.suppliesUsed().get(prayer));
        assertEquals(Integer.valueOf(4), trip.pickedUp().get(prayer));
        assertNull(trip.missed().get(prayer));
    }

    @Test
    public void equipSettledWithinTickIsNeitherSupplyNorGain() {
        // Combined inventory+equipment is unchanged across settled ticks when equipping.
        TripLedger ledger = new TripLedger();
        ledger.updateCarried(carried(ItemKey.item(4151), 1)); // tick 0: whip carried
